<template>
  <div class="lassox-diagram__SyncDialogChangeItem">
    <div :class="[
      'lassox-diagram__SyncDialogChangeItem-label',
      !isGrouped && 'lassox-diagram__SyncDialogChangeItem-label--has-checkbox'
    ]">
      <CheckBoxField
        v-if="!isGrouped"
        class="lassox-diagram__SyncDialogChangeItem-label-checkbox"
        :checked="change.checked"
        @change="checked => {
          change.checked = checked
          if (checked) item.expanded = true
        }"
      />

      <component
        :is="item.fields.length ? 'BaseButton' : 'div'"
        class="lassox-diagram__SyncDialogChangeItem-label-button"
        @click="() => item.expanded = !item.expanded"
      >
        <div class="lassox-diagram__SyncDialogChangeItem-label-text">
          <div v-tooltip="item.isEntity ? item.label : `${item.label} fra ${item.fromEntityLabel} til ${item.toEntityLabel}`">
            <SyncDialogEntityLabel
              v-if="item.isEntity"
              :label="item.label"
            />

            <SyncDialogRelationLabel
              v-else
              :label="item.label"
              :fromEntityLabel="item.fromEntityLabel"
              :toEntityLabel="item.toEntityLabel"
            />
          </div>

          <div
            v-if="infoText"
            class="lassox-diagram__SyncDialogChangeItem-label-info"
          >
            <Icon
              class="lassox-diagram__SyncDialogChangeItem-label-info-icon"
              icon="info"
            />

            <div
              class="lassox-diagram__SyncDialogChangeItem-label-info-text"
              v-text="infoText"
            />
          </div>
        </div>

        <div style="margin: auto" />

        <div
          v-if="!isGrouped"
          :class="[
            'lassox-diagram__SyncDialogChangeItem-label-type',
            `lassox-diagram__SyncDialogChangeItem-label-type--${change.type}`,
          ]"
          v-text="typeLabel"
        />

        <Icon
          v-if="item.fields.length"
          class="lassox-diagram__SyncDialogChangeItem-label-expand-icon"
          :icon="item.expanded ? 'expand_less' : 'expand_more'"
          @click="() => item.expanded = !item.expanded"
        />
      </component>
    </div>

    <div
      v-if="item.fields.length && item.expanded"
      class="lassox-diagram__SyncDialogChangeItem-fields"
    >
      <div
        v-for="(itemField, i) in item.fields"
        :key="i"
        class="lassox-diagram__SyncDialogChangeItem-field"
      >
        <div
          v-if="change.type === 'dataChange'"
          class="lassox-diagram__SyncDialogChangeItem-field-column lassox-diagram__SyncDialogChangeItem-field-column--checkbox"
        >
          <CheckBoxField
            v-if="change.checked"
            class="lassox-diagram__SyncDialogChangeItem-field-checkbox"
            v-model="itemField.checked"
          />

          <CheckBoxField
            v-else
            class="lassox-diagram__SyncDialogChangeItem-field-checkbox"
            :disabled="true"
            :checked="false"
          />
        </div>

        <div class="lassox-diagram__SyncDialogChangeItem-field-column">
          <div
            class="lassox-diagram__SyncDialogChangeItem-field-column-text"
            v-tooltip="itemField.field.title"
            v-text="itemField.field.title"
          />
        </div>

        <div
          v-if="change.type !== 'addition'"
          class="lassox-diagram__SyncDialogChangeItem-field-column"
        >
          <div
            class="lassox-diagram__SyncDialogChangeItem-field-column-text lassox-diagram__SyncDialogChangeItem-field-column-text--old"
            v-tooltip="itemField.currentValueLabel"
            v-text="itemField.currentValueLabel"
          />

          <div
            v-if="itemField.currentInitialValueLabel !== null && itemField.currentInitialValue !== itemField.currentValue"
            class="lassox-diagram__SyncDialogChangeItem-field-column-text"
            v-tooltip="`Ændret fra '${itemField.currentInitialValueLabel}'`"
            v-text="`Ændret fra '${itemField.currentInitialValueLabel}'`"
          />
        </div>

        <div
          v-if="change.type !== 'removal'"
          class="lassox-diagram__SyncDialogChangeItem-field-column"
        >
          <div
            class="lassox-diagram__SyncDialogChangeItem-field-column-text"
            v-tooltip="itemField.newValueLabel"
            v-text="itemField.newValueLabel"
          />
        </div>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { Component, Prop } from 'vue-property-decorator'
import DiagramVue from '../DiagramVue'
import BaseButton from './BaseButton.vue'
import CheckBoxField from './CheckBoxField.vue'
import SyncDialogEntityLabel from './SyncDialogEntityLabel.vue'
import SyncDialogRelationLabel from './SyncDialogRelationLabel.vue'
import Icon from './Icon.vue'
import type { EntityDefinition, EntityType, RelationDefinition, RelationType } from '../diagram'
import type { SyncChange } from './SyncDialogChange.vue'
import type { DataChangeField } from '../types/DiagramUpdater'

export type SyncChangeItem = (
  & (
    | {
      isEntity: true
      isRelation: false
      type: EntityType
      definition?: EntityDefinition
    }
    | {
      isEntity: false
      isRelation: true
      type: RelationType
      definition?: RelationDefinition
      fromEntityLabel: string
      toEntityLabel: string
    }
  )
  & {
    id: string
    label: string
    previouslyDeleted?: boolean
    isCustom?: boolean
    fields: DataChangeField[]
    expanded: boolean
  }
)

@Component({
  components: {
    BaseButton,
    CheckBoxField,
    SyncDialogEntityLabel,
    SyncDialogRelationLabel,
    Icon,
  },
})

export default class SyncDialogChangeItem extends DiagramVue {
  @Prop({ required: true })
  readonly change!: SyncChange

  @Prop({ type: String, required: true })
  readonly typeLabel!: string

  @Prop({ required: true })
  readonly item!: SyncChangeItem

  @Prop({ type: Boolean, default: () => false })
  readonly isGrouped!: boolean

  get infoText () {
    if (this.item.previouslyDeleted) return 'Tidligere fjernet af dig'
    if (this.item.isCustom) return 'Manuelt tilføjet af dig'
    return ''
  }
}
</script>

