      margin: -1px;
      margin-right: 8px - 1px;
    }

    &-text {
      display: flex;
      flex-direction: column;
      margin: -2px 0;
      white-space: normal;
    }

    &-info {
      display: flex;
      align-items: center;
      margin-top: 4px;

      &-icon {
        margin: -1px;
      }

      &-text {
        margin-left: 4px;
      }
    }

    &-type {
      padding: 4px 8px;
      margin: -2px 0;
      margin-left: 8px;
      flex-shrink: 0;
      color: white;
      line-height: 12px;
      font-weight: 500;
      border-radius: 10px;

      &--addition {
        background-color: #66bb6a;
      }

      &--removal {
        background-color: #d17976;
      }

      &--dataChange {
        background-color: #4e79a7;
      }
    }

    &-expand-icon {
      margin: -1px;
      margin-left: 12px - 1px;
    }
  }

  &-label:not(:last-child) &-label-button {
    border-bottom-left-radius: 0;
    border-bottom-right-radius: 0;
  }

  &-fields {
    padding-bottom: 1px;
    margin-top: -1px;
  }

  &-field {
    display: flex;
    align-items: flex-start;
    padding: 12px (6px + 1px);
    padding-top: 12px + 1px;
    box-shadow: inset 0 1px 0 0 rgba(black, 0.12);

    &-column {
      display: flex;
      flex-direction: column;
      align-items: flex-start;
      width: 100%;
      min-width: 0;
      padding: 0 6px;
      flex-shrink: 1;

      &--checkbox {
        width: auto;
        flex-shrink: 0;
      }

      &-text {
        min-width: 0;
        max-width: 100%;
        font-size: 12px;
        line-height: 16px;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;

        &--old {
          text-decoration: line-through;
        }
      }
