<template>
  <FieldContainer
    class="lassox-diagram__EditorField"
    :disabled="!editable"
    :label="title"
    :error="!!errorMessage"
  >
    <template>
      <TextField
        v-if="finalType === 'text'"
        autocomplete="off"
        :name="id"
        :disabled="!editable"
        :error="!!errorMessage"
        :value="value !== undefined ? value : ''"
        @input="e => $emit('change', e.target.value)"
      />

      <TextField
        v-else-if="finalType === 'number'"
        autocomplete="off"
        :name="id"
        type="number"
        :disabled="!editable"
        :error="!!errorMessage"
        :value="value !== undefined ? value : ''"
        @keydown="e => {
          if (e.key == '.' || e.key == ',') e.preventDefault()
        }"
        @input="e => {
          let value = e.target.value

          if (value) {
            const reg = /[^0-9]+/
            if (reg.test(value)) {
              value = value.replace(reg, '')
              e.target.value = value
            }

            const number = e.target.valueAsNumber
            $emit('change', isNaN(number) ? undefined : number)
          } else {
            $emit('change', undefined)
          }
        }"
      />

      <RadioField
        v-else-if="finalType === 'radio-buttons'"
        :name="id"
        :disabled="!editable"
        :options="finalOptions"
        :value="value"
        @change="value => $emit('change', value)"
      />

      <ColorField
        v-else-if="finalType === 'color'"
        :name="id"
        :disabled="!editable"
        :value="value"
        @change="value => $emit('change', value)"
      />
    </template>

    <template
      v-slot:helper-text
      v-if="errorMessage || helperText || showChangedFrom || showReset"
    >
      <div v-if="errorMessage || helperText" v-text="errorMessage || helperText" />

      <div v-if="showChangedFrom || showReset">
        <template v-if="showChangedFrom">
          <template>Ændret</template>
          <template v-if="initialValueLabel"> fra '{{ initialValueLabel }}'</template>
        </template>

        <template v-if="showReset">
          <template v-if="showChangedFrom">. </template>

          <a
            class="lassox-diagram__EditorField_reset-button"
            href="#"
            v-text="'Nulstil'"
            @click.prevent="() => $emit('change', resetValue)"
          />
        </template>
      </div>
    </template>
  </FieldContainer>
</template>

<script lang="ts">
import { Vue, Component, Prop, Model } from 'vue-property-decorator'
import FieldContainer from './FieldContainer.vue'
import TextField from './TextField.vue'
import RadioField from './RadioField.vue'
import ColorField from './ColorField.vue'
import { isRecord } from '../util/type-guards'

interface EditorFieldOption {
  label: string
  value: any
}

const notSet = Symbol('Not set')

@Component({
  components: {
    FieldContainer,
    TextField,
    RadioField,
    ColorField,
  },
})

export default class EditorField extends Vue {
  @Prop(String)
  readonly id?: string

  @Prop({ type: String, required: true })
  readonly type!: string

  @Prop(String)
  readonly title?: string

  @Prop({ type: Boolean, default: true })
  readonly editable!: boolean

  @Prop(Array)
  readonly options?: unknown[]

  @Prop(String)
  readonly helperText?: string

  @Prop({ default: () => notSet })
  readonly initialValue?: any

  @Prop(String)
  readonly initialValueLabel?: string

  @Prop({ default: () => notSet })
  readonly resetValue?: any

  @Model('change')
  readonly value?: any

  @Prop(String)
  readonly errorMessage?: string

  finalType: 'text' | 'number' | 'radio-buttons' | 'color' = 'text'
  finalOptions: EditorFieldOption[] = []

  get hasInitialValue () {
    return this.initialValue !== notSet
  }

  get hasResetValue () {
    return this.resetValue !== notSet
  }

  get showChangedFrom () {
    return this.hasInitialValue && this.value !== this.initialValue
  }

  get showReset () {
    return this.editable && this.hasResetValue && this.value !== this.resetValue
  }

  mounted () {
    this.$watch(
      () => this.type,
      () => {
        this.finalType = 'text'

        switch (this.type) {
          case 'text':
          case 'number':
          case 'radio-buttons':
          case 'color': {
            this.finalType = this.type
            break
          }

          case 'boolean': {
            this.finalType = 'radio-buttons'
            this.finalOptions = [
              {
                label: 'Ja',
                value: true,
              },
              {
                label: 'Nej',
                value: false,
              },
            ]
            break
          }
        }
      },
      { immediate: true },
    )

    this.$watch(
      () => this.options,
      () => {
        if (this.type === 'boolean') return

        this.finalOptions = []

        for (const option of this.options ?? []) {
          if (isRecord(option)) {
            this.finalOptions.push({
              label: typeof option.label === 'string' ? option.label : '',
              value: option.value,
            })
          }
        }
      },
      { immediate: true },
    )
  }
}
</script>

<style lang="scss">
.lassox-diagram__EditorField {
  .lassox-diagram__FieldContainer_helper-text {
    & > div + div {
      margin-top: 8px - 4px;
    }
  }
}
</style>
