<template>
  <div class="lassox-diagram__ColorField">
    <DropdownButton class="lassox-diagram__ColorField-dropdown-button">
      <template v-slot="{ onClick }">
        <BaseButton
          class="lassox-diagram__ColorField-button"
          :disabled="disabled"
          @click="onClick"
        >
          <div
            class="lassox-diagram__ColorField-button-color"
            :style="{ backgroundColor: color.rgbaString }"
          />

          <div class="lassox-diagram__ColorField-button-hex">{{ color.hexString }}</div>
        </BaseButton>
      </template>

      <template v-slot:dropdown-menu="{ close }">
        <ColorPicker
          :color="color"
          @change="onColorChanged"
          @close="close"
        />
      </template>
    </DropdownButton>
  </div>
</template>

<script lang="ts">
import { Vue, Component, Prop, Model } from 'vue-property-decorator'
import DropdownButton from './DropdownButton.vue'
import BaseButton from './BaseButton.vue'
import ColorPicker from './ColorPicker.vue'
import iro from '@jaames/iro'

@Component({
  components: {
    DropdownButton,
    BaseButton,
    ColorPicker,
  },
})

export default class ColorField extends Vue {
  @Prop(String)
  readonly name?: string

  @Prop({ type: Boolean, default: false })
  readonly disabled!: boolean

  @Model('change')
  readonly value?: string

  color = new iro.Color()

  created () {
    if (this.value) this.color.set(this.value)

    this.$watch(
      () => this.value,
      value => {
        if (!value || value === this.color.hexString) return
        this.color = this.color.clone()
        this.color.set(value)
      },
    )
  }

  onColorChanged (color: iro.Color) {
    this.color = color.clone()
    if (color.hexString === this.value) return
    this.$emit('change', color.hexString)
  }
}
</script>

