<template>
  <Dialog
    class="lassox-diagram__EditDiagramDialog"
    dismissable
    :loading="saving"
    :title="title || 'Rediger diagram'"
    size="3x"
    :onClose="close"
  >
    <template v-slot:content>
      <EditorFields>
        <EditorField
          id="diagram-title"
          type="text"
          title="Navn"
          v-model="fields.title"
        />

        <EditorField
          id="diagram-description"
          type="text"
          title="Note"
          v-model="fields.description"
        />

        <EditorField
          v-if="diagram.enableSharing"
          id="diagram-shared"
          type="boolean"
          :editable="isOwner"
          title="Delt med organisationen"
          helperText="Når du deler med organisationen kan andre brugere se og redigere i diagrammet"
          v-model="fields.shared"
        />
      </EditorFields>
    </template>

    <template v-slot:actions>
      <ButtonGroup align="right">
        <Button
          label="Fortryd"
          :disabled="saving"
          @click="close"
        />

        <Button
          label="Gem"
          type="primary"
          :disabled="saving"
          @click="() => {
            const result = save({
              savedDiagram,
              title: fields.title,
              description: fields.description,
              shared: fields.shared,
            })

            saving = true

            if (isPromise(result)) {
              result.then(() => {
                saving = false
                close()
              })
            } else {
              saving = false
              close()
            }
          }"
        />
      </ButtonGroup>
    </template>
  </Dialog>
</template>

<script lang="ts">
import { Vue, Component, Inject, Prop } from 'vue-property-decorator'
import Dialog from './Dialog.vue'
import LoadingSpinner from './LoadingSpinner.vue'
import BaseButton from './BaseButton.vue'
import Icon from './Icon.vue'
import IconButton from './IconButton.vue'
import EditorFields from './EditorFields.vue'
import EditorField from './EditorField.vue'
import CheckBoxField from './CheckBoxField.vue'
import ButtonGroup from './ButtonGroup.vue'
import Button from './Button.vue'
import type DiagramVm from './Diagram.vue'
import type Diagram from '../diagram'
import type SavedDiagram from '../types/SavedDiagram'

@Component({
  components: {
    Dialog,
    LoadingSpinner,
    BaseButton,
    Icon,
    IconButton,
    EditorFields,
    EditorField,
    CheckBoxField,
    ButtonGroup,
    Button,
  },
})

export default class EditDiagramDialog extends Vue {
  @Inject()
  readonly diagramVm!: DiagramVm

  @Inject()
  readonly diagram!: Diagram

  @Prop(String)
  readonly title?: string

  @Prop(Boolean)
  readonly ignoreOwnership?: boolean

  @Prop()
  readonly savedDiagram?: SavedDiagram

  @Prop({ type: Function, required: true })
  readonly save!: () => unknown

  saving = false

  fields = {
    title: '',
    description: '',
    shared: false,
  }

  get isOwner () {
    if (this.ignoreOwnership) return true
    const diagram = this.savedDiagram || this.diagram.activeDiagram
    if (!diagram) return true
    return (diagram.ownerUserId ?? '') === this.diagram.userId
  }

  created () {
    const { title, description, shared } = this.savedDiagram || this.diagram.activeDiagram

    this.fields.title = title ?? ''
    this.fields.description = description ?? ''
    this.fields.shared = !this.isOwner || (shared ?? false)
  }

  isPromise (o: unknown): o is Promise<unknown> {
    return o instanceof Promise
  }

  close () {
    this.$emit('close')
  }
}
</script>
