<template>
  <div
    :class="[
      'lassox-diagram__RadioField',
      disabled ? 'lassox-diagram__RadioField--disabled' : '',
    ]"
  >
    <label
      v-for="(option, i) in finalOptions"
      :key="i"
      :class="[
        'lassox-diagram__RadioField-option',
        option.focused && 'lassox-diagram__RadioField-option--focused',
        option.value === value && 'lassox-diagram__RadioField-option--checked',
      ]"
    >
      <input
        class="lassox-diagram__RadioField-option-input"
        type="radio"
        :name="name"
        :disabled="disabled"
        :value="option.value"
        :checked="option.value === value"
        @focus="option.focused = true"
        @blur="option.focused = false"
        @change="() => $emit('change', option.value)"
      >

      <div class="lassox-diagram__RadioField-option-icon-wrapper">
        <Icon
          class="lassox-diagram__RadioField-option-icon"
          icon="radio_button_unchecked"
        />

        <Icon
          class="lassox-diagram__RadioField-option-icon lassox-diagram__RadioField-option-icon--checked"
          icon="radio_button_checked"
        />
      </div>

      <div class="lassox-diagram__RadioField-option-label">{{ option.label }}</div>
    </label>
  </div>
</template>

<script lang="ts">
import { Vue, Component, Prop, Model, Watch } from 'vue-property-decorator'
import Icon from './Icon.vue'

@Component({
  components: {
    Icon,
  },
})

export default class RadioField extends Vue {
  @Prop(String)
  readonly name?: string

  @Prop({ type: Boolean, default: false })
  readonly disabled!: boolean

  @Prop({ type: Array, required: true })
  readonly options!: ({
    label: string
    value: any
  })[]

  @Model('change')
  readonly value!: any

  finalOptions: ({
    label: string
    value: any
    focused: boolean
  })[] = []

  @Watch('options', { immediate: true })
  onOptionsChanged () {
    this.finalOptions = this.options.map(o => ({
      label: o.label,
      get value () {
        return o.value
      },
      set value (value) {
        o.value = value
      },
      focused: false,
    }))
  }
}
</script>

<style lang="scss">
@use 'sass:math';

.lassox-diagram__RadioField {
  display: flex;
  justify-content: flex-start;
  align-items: flex-start;
  margin: -8px;
  opacity: 1;
  transition: opacity 100ms;

  &-option {
    display: flex;
    justify-content: flex-start;
    align-items: flex-start;
    width: auto;
    flex-grow: 0;
    flex-shrink: 0;
    padding: 8px;
    cursor: pointer;
    user-select: none;
    -webkit-tap-highlight-color: transparent;

    &-input {
      position: fixed;
      top: -100vh;
      left: -100vw;
      width: 0;
      height: 0;
      opacity: 0;
    }

    &-icon-wrapper {
      position: relative;
      margin: -7px;
      border-radius: 50%;
      transition: background-color 100ms;
    }

    &-icon {
      display: flex;
      justify-content: center;
      align-items: center;
      width: 32px;
      height: 32px;
      opacity: 1;
      transition: opacity 100ms;

      &--checked {
        position: absolute;
        top: 0;
        left: 0;
        opacity: 0;
      }
    }

    &--checked &-icon {
      opacity: 0;

      &--checked {
        opacity: 1;
      }
    }

    &-label {
      padding-left: 8px;
      margin-top: 1px;
      font-size: 12px;
      line-height: 16px;
    }
  }

  $this: &;

  @mixin optionStyle (
    $fg,
    $overlay,
  ) {
    $overlayColor: map-get($overlay, 'color');

    #{$this}-option-icon {
      color: $fg;
    }

    &:hover #{$this}-option-icon-wrapper {
      background-color: rgba($overlayColor, math.div(map-get($overlay, 'hover'), 100%));
    }

    &#{$this}-option--focused #{$this}-option-icon-wrapper {
      background-color: rgba($overlayColor, math.div(map-get($overlay, 'focus'), 100%));
    }

    &:active #{$this}-option-icon-wrapper {
      background-color: rgba($overlayColor, math.div(map-get($overlay, 'pressed'), 100%));
    }
  }

  &-option {
    @include optionStyle(
      $fg: #757575,
      $overlay: (
        color: black,
        hover: 4%,
        focus: 8%,
        pressed: 16%,
      ),
    );
  }

  &:not(&--disabled) &-option--checked {
    $color: #ffa07a;

    @include optionStyle(
      $fg: $color,
      $overlay: (
        color: $color,
        hover: 8%,
        focus: 16%,
        pressed: 32%,
      ),
    );
  }

  &--disabled {
    opacity: 0.5;
    pointer-events: none;
  }
}
</style>
