import Vue from 'vue'
import Reffer from './reffer'

export default class ReactiveDictionary<K, V> {
  constructor () {
    Vue.observable(this)
  }

  private _reffer = new Reffer
  private _obj: Record<string, V> = Vue.observable({})

  has (key: K) {
    return this._reffer.getKey(key) in this._obj
  }

  get (key: K): V | undefined {
    return this._obj[this._reffer.getKey(key)]
  }

  set (key: K, value: V) {
    Vue.set(this._obj, this._reffer.getKey(key), value)
    return value
  }

  delete (key: K) {
    Vue.delete(this._obj, this._reffer.getKey(key))
  }
}
