      border-radius: 2px;
      box-shadow: 0 2px 10px 0 rgba(black, 0.2);
      overflow-x: hidden;
      overflow-y: auto;
    }

    &_suggestions-status {
      padding: 10px 12px;
      font-size: 12px;
      line-height: 16px;
      text-align: center;
    }

    &_suggestion {
      display: flex;
      justify-content: flex-start;
      align-items: stretch;
      width: 100%;
      padding: 12px;
      box-sizing: border-box;

      &--active .lassox-diagram__BaseButton_overlay {
        opacity: 0.5;
      }

      &-column-1 {
        min-width: 0;
        flex-grow: 1;
        flex-shrink: 1;
      }

      &-column-2 {
        display: flex;
        justify-content: center;
        align-items: center;
        flex-grow: 0;
        flex-shrink: 0;
        padding-left: 12px;
      }

      &-supertext,
      &-text,
      &-subtext,
      &-side-text {
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;

        &:not(:first-child) {
          margin-top: 4px;
        }
      }

      &-supertext,
      &-subtext,
      &-side-text {
