<template>
  <div class="lassox-diagram__DropdownButton">
    <slot v-bind="{ isOpen, onClick, close }" />

    <DropdownMenu
      :opener="buttonEl"
      :close="close"
    >
      <slot name="dropdown-menu" v-bind="{ isOpen, onClick, close }" />
    </DropdownMenu>
  </div>
</template>

<script lang="ts">
import { Vue, Component } from 'vue-property-decorator'
import Button from './Button.vue'
import DropdownMenu from './DropdownMenu.vue'

@Component({
  components: {
    Button,
    DropdownMenu,
  },
})

export default class DropdownButton extends Vue {
  buttonEl: HTMLElement | null = null

  get isOpen () {
    return !!this.buttonEl
  }

  onClick (event: MouseEvent) {
    const buttonEl = event.currentTarget instanceof HTMLElement
      ? event.currentTarget
      : null

    if (this.buttonEl == buttonEl) {
      this.buttonEl = null
      return
    }

    this.buttonEl = buttonEl
  }

  close () {
    this.buttonEl = null
  }
}
</script>

<style lang="scss">
.lassox-diagram__DropdownButton {
  display: inline-flex;
  flex-grow: 0;
  flex-shrink: 0;
}
</style>
