<template>
  <EditorFields>
    <FieldContainer label="Type">
      <DropdownField
        :options="entityTypeDropdownOptions"
        v-model="entityType"
      />
    </FieldContainer>

    <FieldContainer v-if="searchEnabled && customEnabled">
      <TabBar
        outlined
        :tabs="[
          { id: 'search', label: 'Søg' },
          { id: 'custom', label: 'Manuelt' },
        ]"
        v-model="mode"
      />
    </FieldContainer>

    <template v-if="mode === 'search'">
      <FieldContainer :label="`Søg efter ${entityType.labels.singular.toLowerCase()}`">
        <EntitySearchBar
          :entityType="entityType"
          v-model="selectedSuggestion"
        />
      </FieldContainer>
    </template>

    <template v-else>
      <FieldContainer>
        <DataCreator
          ref="dataCreator"
          :type="entityType"
          :data="entityData"
          @change="newData => {
            entityData = newData
            updateModel()
          }"
        />
      </FieldContainer>
    </template>
  </EditorFields>
</template>

<script lang="ts">
import { Vue, Component, Prop, Inject, Ref } from 'vue-property-decorator'
import type { ContextItem, EntityType } from '../diagram'
import type DiagramVm from './Diagram.vue'
import EditorFields from './EditorFields.vue'
import EditorField from './EditorField.vue'
import DataCreator from './DataCreator.vue'
import FieldContainer from './FieldContainer.vue'
import TabBar from './TabBar.vue'
import DropdownField from './DropdownField.vue'
import EntitySearchBar, { Suggestion } from './EntitySearchBar.vue'

export type EntitySelectorModel = (
  {
    entityType: EntityType
  } & (
    {
      mode: 'search'
      selectedSuggestion: Suggestion
    } | {
      mode: 'custom'
      entityData: Record<string, any>
    }
  )
) | null

@Component({
  components: {
    EntitySearchBar,
    EditorFields,
    EditorField,
    DataCreator,
    FieldContainer,
    TabBar,
    DropdownField,
  },
})

export default class EntitySelector extends Vue {
  @Inject()
  readonly diagramVm!: DiagramVm

  @Ref()
  readonly dataCreator?: DataCreator

  @Prop(Array)
  readonly entityTypes?: EntityType[]

  entityType: EntityType | null = null
  mode: 'search' | 'custom' = 'search'
  selectedSuggestion: Suggestion | null = null
  entityData: Record<string, any> = {}

  get diagram () {
    return this.diagramVm.diagram
  }

  get finalEntityTypes () {
    return this.entityTypes || this.diagram.entityTypes.items
  }

  get searchEnabled () {
    return this.entityType?.searchable ?? false
  }

  get customEnabled () {
    return this.entityType?.customCreatable ?? false
  }

  get entityTypeDropdownOptions () {
    return this.finalEntityTypes
      .filter(type => type.searchable || type.customCreatable)
      .map(type => ({
        id: type.id,
        label: type.labels.singular,
        value: type,
      }))
  }

  validate (contextItem: ContextItem) {
    if (this.mode !== 'custom' || !this.dataCreator) return true
    return this.dataCreator.validate(contextItem)
  }

  updateModel () {
    const { entityType, mode, selectedSuggestion, entityData } = this

    const model = ((): EntitySelectorModel => {
      if (!entityType) return null

      if (mode === 'search') {
        if (!selectedSuggestion) return null
        return {
          entityType,
          mode,
          selectedSuggestion,
        }
      } else {
        return {
          entityType,
          mode,
          entityData,
        }
      }
    })()

    this.$emit('change', model)
  }

  created () {
    this.$watch(
      () => this.entityTypes,
      () => {
        if (this.entityType && this.finalEntityTypes.includes(this.entityType)) return
        this.entityType = this.finalEntityTypes[0] ?? null
      },
      { immediate: true },
    )

    this.$watch(
      () => this.entityType,
      () => {
        this.selectedSuggestion = null
        this.entityData = {}
      },
      { immediate: true },
    )

    this.$watch(
      () => this.mode,
      () => {
        this.selectedSuggestion = null
        this.entityData = {}
      },
      { immediate: true },
    )

    this.$watch(
      () => this.searchEnabled,
      () => {
        if (!this.searchEnabled) this.mode = 'custom'
      },
      { immediate: true },
    )

    this.$watch(
      () => this.customEnabled,
      () => {
        if (!this.customEnabled) this.mode = 'search'
      },
      { immediate: true },
    )

    this.$watch(
      () => [this.entityType, this.mode, this.selectedSuggestion],
      () => {
        this.updateModel()
      },
      { immediate: true },
    )
  }
}
</script>
