<template>
  <div class="lassox-diagram__GraphLegend">
    <img
      v-if="!hideLogo"
      class="lassox-diagram__GraphLegend-logo"
      src="../assets/logo-new.svg"
      alt="Lasso X"
    >

    <div class="lassox-diagram__GraphLegend-fields">
      <div
        v-for="field in fields"
        :key="field.fullId"
        class="lassox-diagram__GraphLegend-field"
      >
        <div
          class="lassox-diagram__GraphLegend-field-legend-color"
          :style="{ backgroundColor: field.legendColor }"
        />

        <div
          class="lassox-diagram__GraphLegend-field-title"
          v-text="field.title"
        />
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { Vue, Component, Inject } from 'vue-property-decorator'
import type DiagramVm from './Diagram.vue'

@Component({})

export default class GraphLegend extends Vue {
  @Inject()
  readonly diagramVm!: DiagramVm

  get diagram () {
    return this.diagramVm.diagram
  }

  get hideLogo () {
    return this.diagram.printSettings.hideLogo
  }

  get fields () {
    return this.diagram.fields.filter(field => field.active && field.addToLegend)
  }
}
</script>

