<template>
  <div
    :class="[
      'lassox-diagram__SyncDialogChange',
      isGrouped && 'lassox-diagram__SyncDialogChange--grouped',
      change.expanded && 'lassox-diagram__SyncDialogChange--expanded',
    ]"
  >
    <div
      v-if="isGrouped"
      class="lassox-diagram__SyncDialogChange-header"
    >
      <CheckBoxField
        class="lassox-diagram__SyncDialogChange-header-checkbox"
        :checked="change.checked"
        @change="checked => {
          change.checked = checked
          if (checked) change.expanded = true
        }"
      />

      <BaseButton
        class="lassox-diagram__SyncDialogChange-header-button"
        @click="() => change.expanded = !change.expanded"
      >
        <div
          v-if="newLabel"
          class="lassox-diagram__SyncDialogChange-header-text"
        >
          <div v-tooltip="newLabel.string">
            <template>{{ newLabel.entityTypeCounts }} relateret til </template>

            <CommaJoin>
              <span
                v-for="(label, i) in newLabel.relatedEntityLabels"
                :key="i"
                class="lassox-diagram__SyncDialogChange-header-text-entity-name"
                v-text="label"
              />
            </CommaJoin>
          </div>

          <div
            v-if="infoText"
            class="lassox-diagram__SyncDialogChange-header-info"
          >
            <Icon
              class="lassox-diagram__SyncDialogChange-header-info-icon"
              icon="info"
            />

            <div
              class="lassox-diagram__SyncDialogChange-header-info-text"
              v-text="infoText"
            />
          </div>
        </div>

        <div
          v-else
          class="lassox-diagram__SyncDialogChange-header-text"
          v-tooltip="change.label"
          v-text="change.label"
        />

        <div
          :class="[
            'lassox-diagram__SyncDialogChange-header-type',
            `lassox-diagram__SyncDialogChange-header-type--${change.type}`,
          ]"
          v-text="typeLabel"
        />

        <Icon
          class="lassox-diagram__SyncDialogChange-header-expand-icon"
          :icon="change.expanded ? 'expand_less' : 'expand_more'"
        />
      </BaseButton>
    </div>

    <div
      v-if="!isGrouped || change.expanded"
      class="lassox-diagram__SyncDialogChange-items"
    >
      <SyncDialogChangeItem
        v-for="(item, i) in change.items"
        :key="i"
        :change="change"
        :typeLabel="typeLabel"
        :item="item"
        :isGrouped="isGrouped"
      />
    </div>
  </div>
</template>

<script lang="ts">
import { Component, Prop, Inject } from 'vue-property-decorator'
import DiagramVue from '../DiagramVue'
import BaseButton from './BaseButton.vue'
import CheckBoxField from './CheckBoxField.vue'
import CommaJoin from './CommaJoin.vue'
import Icon from './Icon.vue'
import SyncDialogChangeItem, { SyncChangeItem } from './SyncDialogChangeItem.vue'
import type { default as Diagram, EntityType } from '../diagram'
import { commaJoin, pluralize } from '../util/string-util'
import { Addition, DataChange, Removal } from '../types/DiagramUpdater'

export type SyncChange = (
  & (
    | { type: 'addition', addition: Addition }
    | { type: 'removal', removal: Removal }
    | { type: 'dataChange', dataChange: DataChange }
  )
  & {
    checked: boolean
    label?: string
    newLabel?: {
      entityTypeCounts: [EntityType, number][]
      relatedEntityLabels: string[]
    }
    items: SyncChangeItem[]
    expanded: boolean
  }
)

@Component({
  components: {
    BaseButton,
    CheckBoxField,
    CommaJoin,
    Icon,
    SyncDialogChangeItem,
  },
})

export default class SyncDialogChange extends DiagramVue {
  @Inject()
  readonly diagram!: Diagram

  @Prop({ required: true })
  readonly change!: SyncChange

  get typeLabel () {
    return ({
      addition: 'Ny',
      removal: 'Fjernet',
      dataChange: 'Ændret',
    })[this.change.type]
  }

  get isGrouped () {
    return this.change.items.length > 1
  }

  get newLabel () {
    if (!this.change.newLabel) return null

    const entityTypeCounts = commaJoin(this.change.newLabel.entityTypeCounts.map(([ type, count ]) => `${count} ${pluralize(count, type.labels.singular, type.labels.plural).toLowerCase()}`))
    const relatedEntityLabels = this.change.newLabel.relatedEntityLabels

    return {
      entityTypeCounts,
      relatedEntityLabels,
      string: `${entityTypeCounts} relateret til ${commaJoin(relatedEntityLabels)}`,
    }
  }

  get previouslyDeleted () {
    return this.change.items.every(item => item.previouslyDeleted)
  }

  get isCustom () {
    return this.change.items.every(item => item.isCustom)
  }

  get infoText () {
    if (this.previouslyDeleted) return 'Tidligere fjernet af dig'
    if (this.isCustom) return 'Manuelt tilføjet af dig'
    return ''
  }
}
</script>

