<template>
  <Dialog
    class="lassox-diagram__ConfirmAdditionDialog"
    size="2x"
    :dismissable="true"
    title="Bekræft ændringer"
    :content="content"
    :onClose="dismiss"
  >
    <template v-slot:actions>
      <CheckBoxField
        label="Bevar layout"
        :checked="!runLayout"
        @change="checked => runLayout = !checked"
      />

      <div
        :style="{
          width: '16px',
          flexGrow: '0',
          flexShrink: '0',
          margin: 'auto',
        }"
      />

      <ButtonGroup align="right">
        <Button
          label="Fortryd"
          @click="dismiss"
        />

        <Button
          label="Tilføj"
          type="primary"
          @click="confirm"
        />
      </ButtonGroup>
    </template>
  </Dialog>
</template>

<script lang="ts">
import { Vue, Component, Prop, Inject } from 'vue-property-decorator'
import Dialog from './Dialog.vue'
import CheckBoxField from './CheckBoxField.vue'
import ButtonGroup from './ButtonGroup.vue'
import Button from './Button.vue'
import type DiagramVm from './Diagram.vue'
import type { DiagramDataDefinition } from '../types/DiagramData'
import type { Entity } from '../diagram'

@Component({
  components: {
    Dialog,
    CheckBoxField,
    ButtonGroup,
    Button,
  },
})

export default class ConfirmAdditionDialog extends Vue {
  @Inject()
  readonly diagramVm!: DiagramVm

  @Prop({ type: Object, required: true })
  readonly data!: DiagramDataDefinition

  @Prop({ type: Array })
  readonly entitiesToMarkAsExpanded?: Entity[]

  @Prop(Function)
  readonly onConfirm?: () => void

  @Prop(Function)
  readonly onDismiss?: () => void

  runLayout = true

  get diagram () {
    return this.diagramVm.diagram
  }

  get content () {
    const typeCounts = new Map<string, number>()

    for (const relation of this.data.relations ?? []) {
      const type = relation.type
      typeCounts.set(type, (typeCounts.get(type) ?? 0) + 1)
    }

    if (typeCounts.size) {
      let typeCountsString = ''

      let i = 0
      for (const [ typeId, count ] of typeCounts) {
        i++
        const type = this.diagram.relationTypes.get(typeId)

        if (typeCountsString) {
          typeCountsString += i == typeCounts.size
            ? ' og '
            : ', '
        }

        typeCountsString += `${count} ${type.labels[count == 1 ? 'singular' : 'plural'].toLowerCase()}`
      }

      return `Der vil blive tilføjet ${typeCountsString} til diagrammet. Vil du forstætte?`
    }

    return `Der vil blive tilføjet ${this.data.entities?.length ?? 0} entiteter til diagrammet. Vil du fortsætte?`
  }

  created () {
    this.runLayout = this.diagram.userPreferences.runLayoutAfterAddition
  }

  close () {
    this.$emit('close')
  }

  confirm () {
    this.close()
    this.onConfirm?.()

    this.diagram.activeDiagram.data.commitChange({
      add: this.data,
    }, {
      entitiesToMarkAsExpanded: this.entitiesToMarkAsExpanded,
    })

    const layout = this.runLayout && this.diagram.activeDiagram.settings.activeLayout

    if (layout) requestAnimationFrame(() => {
      this.diagram.eventBus.emit({ name: 'graph.layout', layout, applyToLastChange: true })
    })

    if (this.runLayout !== this.diagram.userPreferences.runLayoutAfterAddition) {
      this.diagram.userPreferences.runLayoutAfterAddition = this.runLayout
    }
  }

  dismiss () {
    this.close()
    this.onDismiss?.()
  }
}
</script>

<style lang="scss">
.lassox-diagram__ConfirmAdditionDialog {
  .lassox-diagram__Dialog-actions {
    display: flex;
    align-items: center;
  }
}
</style>
