<template>
  <div
    :class="[
      'lassox-diagram__CheckBoxField',
      disabled ? 'lassox-diagram__CheckBoxField--disabled' : '',
    ]"
  >
    <label
      :class="[
        'lassox-diagram__CheckBoxField-option',
        focused && 'lassox-diagram__CheckBoxField-option--focused',
        checked && 'lassox-diagram__CheckBoxField-option--checked',
      ]"
    >
      <input
        class="lassox-diagram__CheckBoxField-option-input"
        type="checkbox"
        :name="name"
        :disabled="disabled"
        :checked="checked"
        @focus="focused = true"
        @blur="focused = false"
        @change="() => $emit('change', !checked)"
      >

      <div class="lassox-diagram__CheckBoxField-option-icon-wrapper">
        <Icon
          class="lassox-diagram__CheckBoxField-option-icon"
          icon="check_box_outline_blank"
        />

        <Icon
          class="lassox-diagram__CheckBoxField-option-icon lassox-diagram__CheckBoxField-option-icon--checked"
          icon="check_box"
        />
      </div>

      <div
        v-if="label"
        class="lassox-diagram__CheckBoxField-option-label"
        v-text="label"
      />
    </label>
  </div>
</template>

<script lang="ts">
import { Vue, Component, Prop, Model } from 'vue-property-decorator'
import Icon from './Icon.vue'

@Component({
  components: {
    Icon,
  },
})

export default class CheckBoxField extends Vue {
  @Prop(String)
  readonly name?: string

  @Prop({ type: Boolean, default: false })
  readonly disabled!: boolean

  @Prop({ type: String, required: false })
  readonly label?: string

  @Model('change', { type: Boolean, default: false })
  readonly checked!: boolean

  focused = false
}
</script>

<style lang="scss">
@use 'sass:math';

.lassox-diagram__CheckBoxField {
  display: flex;
  justify-content: flex-start;
  align-items: flex-start;
  // margin: -8px;
  opacity: 1;
  transition: opacity 100ms;

  &-option {
    display: flex;
    justify-content: flex-start;
    align-items: flex-start;
    width: auto;
    flex-grow: 0;
    flex-shrink: 0;
    // padding: 8px;
    cursor: pointer;
    user-select: none;
    -webkit-tap-highlight-color: transparent;

    &-input {
      position: fixed;
      top: -100vh;
      left: -100vw;
      width: 0;
      height: 0;
      opacity: 0;
    }

    &-icon-wrapper {
      position: relative;
      margin: -8px;
      border-radius: 50%;
      transition: background-color 100ms;
    }

    &-icon {
      display: flex;
      justify-content: center;
      align-items: center;
      width: 32px;
      height: 32px;
      opacity: 1;
      transition: opacity 100ms;

      &--checked {
        position: absolute;
        top: 0;
        left: 0;
        opacity: 0;
      }
    }

    &--checked &-icon {
      opacity: 0;

      &--checked {
        opacity: 1;
      }
    }

    &-label {
      padding-top: 2px;
      padding-left: 8px;
      margin: -2px 0;
      font-size: 12px;
      line-height: 16px;
    }
  }

  $this: &;

  @mixin optionStyle (
    $fg,
    $overlay,
  ) {
    $overlayColor: map-get($overlay, 'color');

    #{$this}-option-icon {
      color: $fg;
    }

    &:hover #{$this}-option-icon-wrapper {
      background-color: rgba($overlayColor, math.div(map-get($overlay, 'hover'), 100%));
    }

    &#{$this}-option--focused #{$this}-option-icon-wrapper {
      background-color: rgba($overlayColor, math.div(map-get($overlay, 'focus'), 100%));
    }

    &:active #{$this}-option-icon-wrapper {
      background-color: rgba($overlayColor, math.div(map-get($overlay, 'pressed'), 100%));
    }
  }

  &-option {
    @include optionStyle(
      $fg: #757575,
      $overlay: (
        color: black,
        hover: 4%,
        focus: 8%,
        pressed: 16%,
      ),
    );
  }

  &:not(&--disabled) &-option--checked {
    $color: #ffa07a;

    @include optionStyle(
      $fg: $color,
      $overlay: (
        color: $color,
        hover: 8%,
        focus: 16%,
        pressed: 32%,
      ),
    );
  }

  &--disabled {
    opacity: 0.5;
    pointer-events: none;
  }
}
</style>
