<template>
  <div
    class="lassox-diagram__GraphPrint"
    :style="{
      width: `${contentSize.width}px`,
      height: `${contentSize.height}px`,
    }"
  >
    <div
      v-if="printing"
      ref="printContentEl"
      class="lassox-diagram__GraphPrint-print-content"
      :style="{
        width: `${contentSize.width}px`,
        height: `${contentSize.height}px`,
      }"
    >
      <div
        class="lassox-diagram__GraphPrint-print-content-title"
        v-text="title"
      />

      <Graph
        ref="graphVm"
        printMode
        :scaling="graphScaling"
        @readyToPrint="onReadyToPrint"
      />

      <GraphLegend />
    </div>
  </div>
</template>

<script lang="ts">
import { Vue, Component, Inject, Ref } from 'vue-property-decorator'
import Graph from './Graph.vue'
import GraphLegend from './GraphLegend.vue'
import type DiagramVm from './Diagram.vue'
import { createContextItem, PrintContext } from '../diagram'
import { formatDate } from '../util/format-date'
import type cytoscape from 'cytoscape'
import html2canvas from 'html2canvas'

const nextFrame = () => new Promise<void>(resolve => requestAnimationFrame(() => resolve()))

const mmToPx = (mm: number) => mm * 3.78

const paperSizesMm = {
  'A5': [ 210, 148.5 ],
  'A4': [ 297, 210 ],
  'A3': [ 420, 297 ],
}

const paperMarginMm = 10

@Component({
  components: {
    Graph,
    GraphLegend,
  },
})

export default class GraphPrint extends Vue {
  @Inject()
  readonly diagramVm!: DiagramVm

  @Ref()
  readonly printContentEl?: HTMLDivElement

  @Ref()
  readonly graphVm?: Graph

  printing = false
  scaling = 1
  graphScaling = 1
  title = ''

  mode: 'print' | 'pdf' | 'png' = 'print'

  paperOrientation: 'portrait' | 'landscape' | null = null
  paperSize: 'A5' | 'A4' | 'A3' | null = null
  includeMargin = false

  width = 0
  height = 0

  grow: boolean | 'width' | 'height' = false
  get growWidth () { return this.grow === 'width' || this.grow === true }
  get growHeight () { return this.grow === 'height' || this.grow === true }

  rotate = false

  contentSize = { width: 0, height: 0 }

  get diagram () {
    return this.diagramVm.diagram
  }

  mounted () {
    this.diagram.eventBus.on('print', event => {
      if (this.printing) return

      this.printing = true
      this.mode = event.mode

      if (event.scaling) this.scaling = Math.min(Math.max(event.scaling, 1), 4)

      if (event.paperSize) {
        const paperOrientation = event.paperOrientation ?? 'landscape'
        const paperSize = event.paperSize

        if (event.paper) {
          this.paperOrientation = paperOrientation
          this.paperSize = paperSize
          this.includeMargin = event.includeMargin
        }

        const [ paperWidth, paperHeight ] = (() => {
          let size = paperSizesMm[paperSize]
          if (paperOrientation === 'portrait') size = [ size[1], size[0] ]
          return size
        })()

        this.width = paperWidth
        this.height = paperHeight
      }

      if (event.width !== undefined) this.width = event.width
      if (event.height !== undefined) this.height = event.height

      this.grow = event.grow ?? false
    })
  }

  async onReadyToPrint (graph: cytoscape.Core) {
    const cleanup = (file?: { filename: string, blob: Blob }) => {
      this.printing = false
      this.scaling = 1
      this.graphScaling = 1
      this.title = ''

      this.paperOrientation = null
      this.paperSize = null
      this.includeMargin = false

      this.width = 0
      this.height = 0

      this.grow = false

      this.rotate = false

      this.contentSize = { width: 0, height: 0 }

      this.diagram.eventBus.emit({ name: 'printDone', file })
    }

    if (!this.printing || !this.printContentEl) return cleanup()

    const { diagram } = this
    const { activeDiagram } = diagram
    const { data } = activeDiagram

    if (!data.mainEntity) return cleanup()

    const date = new Date()

    const context: PrintContext = {
      mainEntity: createContextItem(data.mainEntity),
      hasDataChanges: [
        ...data.initialData.changes,
        ...data.changes.map(c => c.change),
      ].some(change => change.add || change.remove || change.edit),
      hasCustomizedData: false,
      date: date,
      formattedDate: formatDate(date),
      formattedTime: [
        `${date.getHours()}`.padStart(2, '0'),
        `${date.getMinutes()}`.padStart(2, '0'),
        `${date.getSeconds()}`.padStart(2, '0'),
      ].join(':'),
      historicalDate: activeDiagram.historicalDate,
      formattedHistoricalDate: activeDiagram.historicalDate ? formatDate(activeDiagram.historicalDate) : '',
    }

    // Find custom data changes
    context.hasCustomizedData = (() => {
      const fieldValueNormalizers = {
        text: (value: unknown) => `${value ?? ''}`,
        boolean: (value: unknown) => !!value,
      }

      for (const items of [ data.entities, data.relations ]) {
        for (const item of items) {
          // If we find a custom entity/relation, we have custom data.
          if (item.isCustom) {
            return true
          }

          // If any field has a custom value, we have custom data.
          for (const { fields } of item.fieldGroups) {
            for (const field of fields) {
              const normalizeValue = fieldValueNormalizers[field.type]
              const value = normalizeValue(field.getValue(item.data))
              const initialValue = normalizeValue(field.getValue(item.initialState.data))
              if (value !== initialValue) {
                return true
              }
            }
          }
        }
      }

      // Check if any non-custom entities/relations have been deleted.
      for (const changes of [ data.initialData.changes, data.changes.map(c => c.change) ]) {
        for (const change of changes) {
          if (!change.remove) {
            continue
          }

          if (change.remove.entities) {
            for (const id of change.remove.entities) {
              // Ignore removed custom entities
              // Ignore previously removed entities that exist again
              if (id.startsWith('CUSTOM-ENTITY-') || data.entitiesMap.has(id)) {
                continue
              }

              return true
            }
          }

          if (change.remove.relations) {
            for (const id of change.remove.relations) {
              // Ignore removed custom relations
              // Ignore previously removed relations that exist again
              if (id.startsWith('CUSTOM-RELATION-') || data.relationsMap.has(id)) {
                continue
              }

              return true
            }
          }
        }
      }

      return false
    })()

    // Set title
    if (this.diagram.methods.getPrintTitle) {
      this.title = this.diagram.methods.getPrintTitle(context)
    } else {
      this.title = ''

      if (context.hasCustomizedData) {
        this.title += 'Manuelt tilpasset ejerstruktur'
      } else if (context.historicalDate) {
        this.title += 'Historisk ejerstruktur'
      } else {
        this.title += 'Ejerstruktur'
      }

      if (context.formattedHistoricalDate && !context.hasCustomizedData) {
        this.title += ` pr. ${context.formattedHistoricalDate}`
      } else {
        this.title += ` d. ${context.formattedDate} kl. ${context.formattedTime}`
      }
    }

    const filename = (
      (
        this.diagram.methods.getPrintFilename?.(context)
        ?? `ejerdiagram-${context.formattedDate}-${context.formattedTime}`
      )
      .replace(/[ .:]+/g, '-')
      .replace(/[^\w-]+/g, '')
    )

    await this.$nextTick()

    const fit = async () => {
      this.graphVm?.fit()
      await graph.promiseOn('render')
    }

    const resize = async ({ width, height }: Partial<Record<'width' | 'height', number>>) => {
      let changed = false

      if (typeof width === 'number' && width !== this.contentSize.width) {
        this.contentSize.width = width
        changed = true
      }

      if (typeof height === 'number' && height !== this.contentSize.height) {
        this.contentSize.height = height
        changed = true
      }

      if (!changed) return

      await this.$nextTick()
      await graph.promiseOn('resize')
      await graph.promiseOn('render')
    }

    let { w: graphWidth, h: graphHeight } = graph.elements('[!hiddenByFilter]').boundingBox({})
    graphWidth += 16 * 2
    graphHeight += 16 * 2

    const graphRatio = graphWidth / graphHeight

    const newContentSize = {
      width: this.width,
      height: this.height,
    }

    if (!this.width) {
      if (!this.height) {
        newContentSize.width = graphWidth
        newContentSize.height = graphHeight
      } else {
        newContentSize.width = Math.min(this.height * graphRatio, graphWidth)
      }
    } else if (!this.height) {
      newContentSize.height = Math.min(this.width / graphRatio, graphHeight)
    }

    if (this.paperSize) {
      if (this.includeMargin) {
        newContentSize.width -= paperMarginMm * 2
        newContentSize.height -= paperMarginMm * 2
      }

      newContentSize.width = mmToPx(newContentSize.width)
      newContentSize.height = mmToPx(newContentSize.height)
    }

    await resize(newContentSize)

    let pages = 1

    if (this.graphVm?.el) {
      const { width: graphElWidth, height: graphElHeight } = this.graphVm.el.getBoundingClientRect()

      if (this.width && this.height) {
        const graphElRatio = graphElWidth / graphElHeight

        if (graphElRatio < graphRatio) {
          if (this.growWidth) {
            const desiredGraphWidth = Math.min(graphElHeight, graphHeight) * graphRatio

            if (this.paperSize) {
              pages = Math.max(Math.round(desiredGraphWidth / graphElWidth), 1)
              newContentSize.width *= pages
              this.rotate = this.mode !== 'png' && pages > 1
            } else {
              newContentSize.width = desiredGraphWidth
            }
          }
        } else if (graphElRatio > graphRatio) {
          if (this.growHeight) {
            const desiredGraphHeight = Math.min(graphElWidth, graphWidth) / graphRatio

            if (this.paperSize) {
              pages = Math.max(Math.round(desiredGraphHeight / graphElHeight), 1)
              newContentSize.height *= pages
            } else {
              newContentSize.height = desiredGraphHeight + Math.ceil(newContentSize.height - graphElHeight)
            }
          }
        }
      } else if (!this.height) {
        const diff = Math.ceil(newContentSize.height - graphElHeight)
        if (diff > 0) newContentSize.height = newContentSize.height + diff
      }
    }

    await resize(newContentSize)

    // const zoom = graph.zoom()

    // if (zoom < 1) {
    //   const minScaling = 1
    //   const maxScaling = 4
    //   const range = maxScaling - minScaling

    //   this.graphScaling = minScaling + range * (1 - zoom)

    //   await this.$nextTick()
    //   await graph.promiseOn('render')
    //   await nextFrame()
    // }

    if (this.scaling > 1) {
      this.graphScaling = this.scaling
      await this.$nextTick()
      await graph.promiseOn('resize')
      await graph.promiseOn('render')
      await nextFrame()
    }

    await new Promise(resolve => setTimeout(resolve, 10))
    graph.maxZoom(this.graphScaling)
    await fit()
    await new Promise(resolve => setTimeout(resolve, 10))

    let canvas = await html2canvas(this.printContentEl, {
      logging: false,
      scale: this.scaling,
    })

    if (this.rotate) {
      const oldCanvas = canvas

      canvas = document.createElement('canvas')
      canvas.width = oldCanvas.height
      canvas.height = oldCanvas.width

      const ctx = canvas.getContext('2d')
      const oldCtx = oldCanvas.getContext('2d')

      if (!ctx || !oldCtx) throw 'Could not create canvas'

      ctx.translate(oldCanvas.height, 0)
      ctx.rotate(90 * (Math.PI / 180))
      ctx.drawImage(oldCanvas, 0, 0)

      oldCanvas.remove()
    }

    let nullableBlob = await new Promise<Blob | null>(resolve => canvas.toBlob(resolve, 'image/png'))

    canvas.remove()

    if (!nullableBlob) {
      console.error('Something went wrong when trying to get canvas blob')
      return cleanup()
    }

    let blob = nullableBlob

    if (this.mode === 'print') {
      const base64 = await new Promise<string>(resolve => {
        const reader = new FileReader()
        reader.onloadend = () => resolve(reader.result as string)
        reader.readAsDataURL(blob)
      })

      const iFrameEl = document.createElement('iframe')
      iFrameEl.className = 'lassox-diagram__GraphPrint-iframe'
      iFrameEl.style.width = `${this.contentSize.width}px`
      iFrameEl.style.height = `${this.contentSize.height}px`
      document.body.appendChild(iFrameEl)

      const iFrameWindow = iFrameEl.contentWindow

      const cleanupPrint = () => {
        iFrameEl.src = 'about:blank'
        iFrameEl.remove()
        cleanup()
      }

      if (!iFrameWindow) return cleanupPrint()

      let orientation = this.paperOrientation
      if (this.rotate) orientation = orientation === 'portrait' ? 'landscape' : 'portrait'

      iFrameWindow.document.head.innerHTML = [
        '<style>',
        '@page {',
        `  size: ${this.paperSize} ${orientation};`,
        `  margin: ${this.includeMargin ? 10 : 0}mm;`,
        '}',
        'html, body {',
        '  padding: 0;',
        '  margin: 0;',
        '  overflow: hidden;',
        '}',
        'html {',
        `  width: 100%;`,
        `  height: ${pages * 100}%;`,
        '}',
        'body {',
        '  width: 100%;',
        '  height: 100%;',
        '}',
        '</style>',
      ].join('\n')

      const img = document.createElement('img')
      img.style.display = 'block'
      img.style.width = '100vw'
      img.style.height = `${pages * 100}vh`

      iFrameWindow.document.body.appendChild(img)

      img.src = base64

      await nextFrame()

      if (iFrameWindow.document.readyState !== 'complete') {
        await new Promise<void>(resolve => {
          const cb = () => {
            iFrameEl.removeEventListener('load', cb)
            resolve()
          }

          iFrameEl.addEventListener('load', cb)
        })
      }

      const onAfterPrint = () => {
        iFrameWindow.removeEventListener('afterprint', onAfterPrint)
        requestAnimationFrame(cleanupPrint)
      }

      iFrameWindow.addEventListener('afterprint', onAfterPrint)
      iFrameWindow.print()

      return
    }

    if (this.mode === 'pdf') {
      if (!this.diagram.methods.convertPngToPdf) return cleanup()

      const paperSize = this.paperSize ?? 'A4'
      const paperOrientation = this.paperOrientation ?? 'landscape'

      const pdfBlob = await this.diagram.methods.convertPngToPdf({
        blob,
        title: this.title,
        filename: `${filename}.png`,
        size: paperSize,
        orientation: this.rotate
          ? paperOrientation === 'portrait'
            ? 'landscape'
            : 'portrait'
          : paperOrientation,
        includeMargin: this.includeMargin,
        pageCount: pages,
      }).catch(reason => {
        console.error('Failed to convert png to pdf. Reason:', reason)
        return null
      })

      if (!pdfBlob) return cleanup()

      blob = pdfBlob
    }

    cleanup({
      filename: `${filename}.${this.mode === 'pdf' ? 'pdf' : 'png'}`,
      blob,
    })
  }
}
</script>

<style lang="scss">
.lassox-diagram__GraphPrint {
  position: absolute;
  bottom: 100%;
  right: 100%;
  // z-index: 999999999;
  box-sizing: border-box;
  overflow: hidden;

  &-print-content {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    display: flex;
    flex-direction: column;
    box-sizing: border-box;
    background-color: white;

    &-title {
      flex-shrink: 0;
      padding: 16px;
      padding-bottom: 0;
      color: #000;
      font-size: 14px;
      line-height: 16px;
    }

    .lassox-diagram__Graph {
      width: 100%;
      height: 1px;
      flex-grow: 1;
      flex-shrink: 1;
    }

    .lassox-diagram__GraphLegend {
      flex-shrink: 0;
    }
  }

  &-iframe {
    visibility: hidden;
    position: fixed;
    right: 100%;
    bottom: 100%;
    padding: 0;
    border: 0;
    margin: 0;
  }
}
</style>
