export type MapKey<M> = M extends Map<infer K, any> ? K : never
export type MapValue<M> = M extends Map<any, infer V> ? V : never

export function mapGetOrSet<M extends Map<any, any>> (map: M, key: MapKey<M>, getDefault: () => MapValue<M>) {
  let value: MapValue<M> | undefined = map.get(key)
  if (value === undefined) {
    value = getDefault()
    map.set(key, value)
  }
  return value as MapValue<M>
}

type ArrayToMapKVParam<T> = keyof T | ArrayToMapGetter<T, any> | undefined

type ArrayToMapGetter<T, K> = (item: T, index: number) => K

type ArrayToMapKV<T, Param> = (
  Param extends ArrayToMapKVParam<T>
  ? Param extends keyof T
  ? T[Param]
  : Param extends (item: T, index: number) => infer K
  ? K
  : T
  : never
)

function getKV<T, K extends keyof T> (item: T, index: number, key: K): T[K]

function getKV<T, KV> (item: T, index: number, getKey: (item: T, index: number) => KV): KV

function getKV<T> (item: T, index: number, key: undefined): T

function getKV<T> (item: T, index: number, key: ArrayToMapKVParam<T>) {
  if (typeof key === 'string') return item[key]
  if (typeof key === 'function') return key(item, index)
  return item
}

export function arrayToMap<
  T,
  K extends ArrayToMapKVParam<T> = undefined,
  V extends ArrayToMapKVParam<T> = undefined,
> (
  array: T[],
  key?: K,
  value?: V,
) {
  const getKey: (item: T, index: number, key: ArrayToMapKVParam<T>) => ArrayToMapKV<T, K> = getKV
  const getValue: (item: T, index: number, key: ArrayToMapKVParam<T>) => ArrayToMapKV<T, V> = getKV
  return new Map(array.map((item, index) => [ getKey(item, index, key), getValue(item, index, value) ]))
}

export function mapByKey<T, K extends keyof T | ArrayToMapGetter<T, any>> (array: T[], key: K) {
  return arrayToMap(array, key)
}

export function mapByValue<T, K extends keyof T | ArrayToMapGetter<T, any>> (array: T[], key: K) {
  return arrayToMap(array, undefined, key)
}
