<template>
  <button
    :class="[
      'lassox-diagram__BaseButton',
      disabled && 'lassox-diagram__BaseButton--disabled',
    ]"
    :disabled="disabled"
    v-on="{
      ...$listeners,
      click: e => !disabled && $emit('click', e),
    }"
  >
    <slot />

    <Icon
      v-if="finalLeadingIcon"
      class="lassox-diagram__BaseButton_leading-icon"
      :icon="finalLeadingIcon"
      :style="{ color: finalLeadingIconColor }"
    />

    <div
      v-if="label"
      class="lassox-diagram__BaseButton_label"
      v-text="label"
    />

    <Icon
      v-if="finalTrailingIcon"
      class="lassox-diagram__BaseButton_trailing-icon"
      :icon="finalTrailingIcon"
      :style="{ color: finalTrailingIconColor }"
    />

    <div class="lassox-diagram__BaseButton_outline" />

    <div class="lassox-diagram__BaseButton_overlay" />
  </button>
</template>

<script lang="ts">
import { Vue, Component, Prop } from 'vue-property-decorator'
import Icon from './Icon.vue'

@Component({
  components: {
    Icon,
  },
})

export default class BaseButton extends Vue {
  @Prop({ type: String })
  readonly label?: string

  @Prop({ type: String })
  readonly icon?: string

  @Prop({ type: String })
  readonly leadingIcon?: string

  @Prop({ type: String })
  readonly trailingIcon?: string

  @Prop({ type: String })
  readonly iconColor?: string

  @Prop({ type: String })
  readonly leadingIconColor?: string

  @Prop({ type: String })
  readonly trailingIconColor?: string

  get finalLeadingIcon () {
    return this.leadingIcon ?? this.icon ?? ''
  }

  get finalTrailingIcon () {
    return this.trailingIcon ?? ''
  }

  get finalLeadingIconColor () {
    return this.leadingIconColor ?? this.iconColor ?? ''
  }

  get finalTrailingIconColor () {
    return this.trailingIconColor ?? ''
  }

  @Prop({ type: Boolean, default: false })
  readonly disabled!: boolean
}
</script>

<style lang="scss">
@mixin buttonReset {
  appearance: none;
  padding: 0;
  border: none;
  margin: 0;
  box-sizing: border-box;
  color: inherit;
  font-family: inherit;
  font-size: inherit;
  line-height: inherit;
  font-weight: inherit;
  text-align: inherit;
  background-color: transparent;
  -webkit-tap-highlight-color: transparent;
}

.lassox-diagram__BaseButton {
  @include buttonReset;
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  white-space: nowrap;
  opacity: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  cursor: pointer;
  user-select: none;
  transition: color 100ms, background-color 100ms, opacity 100ms;

  & > &_label {
    font-size: 12px;
    line-height: 1;
  }

  & > .lassox-diagram__Icon {
    box-sizing: content-box;
  }

  & > &_leading-icon + &_label,
  & > &_label + &_trailing-icon {
    padding-left: 8px;
  }

  & > &_outline {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    pointer-events: none;
    border-radius: inherit;
    color: transparent;
    box-shadow: inset 0 0 0 1px;
    transition: box-shadow 100ms;
  }

  & > &_overlay {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    pointer-events: none;
    background-color: rgba(black, 0.16);
    opacity: 0;
    transition: background-color 100ms, opacity 100ms;
  }

  &:hover > &_overlay {
    opacity: 0.25;
  }

  &:focus {
    outline: none;
  }

  &:focus > &_overlay {
    opacity: 0.5;
  }

  &:active > &_overlay {
    opacity: 1;
  }

  &--disabled {
    pointer-events: none;
    opacity: 0.5;
  }

  &--disabled > &_overlay {
    opacity: 0;
  }
}
</style>
