import Vue from 'vue'
import { Component, Prop } from 'vue-property-decorator'
import type { VueConstructor } from 'vue/types/umd'
import type Diagram from './diagram'
import PrintDialog from './components/PrintDialog.vue'
import LoadDialog from './components/LoadDialog.vue'
import ConfirmDialog from './components/ConfirmDialog.vue'
import Toast from './components/Toast.vue'

interface StoreProps {
  diagram: Diagram
}

@Component({})

export class Store extends Vue {
  @Prop({ required: true })
  readonly props!: StoreProps

  get diagram () { return this.props.diagram }

  lastDialogId = 0

  dialogs: ({
    id: number
    component: VueConstructor
    props?: any
  })[] = []

  lastToastId = 0

  toasts: ({
    id: number
    component: VueConstructor
    props?: any
  })[] = []

  showDialog (component: VueConstructor, props?: any) {
    this.dialogs.push({
      id: this.lastDialogId++,
      component,
      props,
    })
  }

  showConfirmDialog (props: {
    title?: string
    content?: string
    confirmButtonText?: string
    dismissButtonText?: string
    onConfirm?: () => void
    onDismiss?: () => void
  }) {
    this.showDialog(ConfirmDialog, props)
  }

  showPrintDialog (mode: 'print' | 'pdf' | 'png') {
    this.showDialog(PrintDialog, { mode })
  }

  showLoadDialog () {
    this.showDialog(LoadDialog)
  }

  showToast (props: {
    content: string,
    dismissable?: boolean,
    duration?: number,
    showLoadingSpinner?: boolean,
  }) {
    const id = this.lastToastId++
    this.toasts.push({ id, component: Toast, props })

    return () => {
      let i = 0

      for (const toast of this.toasts) {
        if (toast.id === id) {
          this.toasts.splice(i, 1)
          return
        }

        i++
      }
    }
  }
}

export const createStore = (props: StoreProps) => new Store({ propsData: { props } })
