<template>
  <Dialog
    class="lassox-diagram__LoadDialog"
    :dismissable="diagram.hasActiveDiagram"
    :loading="loading"
    title="Indlæs diagram"
    size="3x"
    :onClose="close"
  >
    <template v-slot:content>
      <div class="lassox-diagram__LoadDialog-saved-diagrams">
        <BaseButton
          :class="[
            'lassox-diagram__LoadDialog-saved-diagram',
            selectedDiagram === 'new' && 'lassox-diagram__LoadDialog-saved-diagram--selected',
          ]"
          @click="() => selectedDiagram = 'new'"
        >
          <div class="lassox-diagram__LoadDialog-saved-diagram-icons">
            <Icon icon="add" />
          </div>

          <div class="lassox-diagram__LoadDialog-saved-diagram-text">
            <div
              class="lassox-diagram__LoadDialog-saved-diagram-title"
              v-text="'Nyt diagram'"
            />

            <div
              class="lassox-diagram__LoadDialog-saved-diagram-description"
              v-text="'Opret et nyt diagram med seneste data'"
            />
          </div>

          <div
            v-if="defaultDiagram.new"
            class="lassox-diagram__LoadDialog-saved-diagram-actions"
          >
            <Icon icon="check" />
          </div>
        </BaseButton>

        <BaseButton
          v-for="savedDiagram in diagram.savedDiagrams"
          :key="savedDiagram.id"
          :class="[
            'lassox-diagram__LoadDialog-saved-diagram',
            savedDiagram.id === diagram.activeDiagram.id && 'lassox-diagram__LoadDialog-saved-diagram--active',
            savedDiagram === selectedDiagram && 'lassox-diagram__LoadDialog-saved-diagram--selected',
          ]"
          @click="() => selectedDiagram = savedDiagram"
        >
          <div class="lassox-diagram__LoadDialog-saved-diagram-icons">
            <Icon
              v-if="diagram.enableSharing"
              :icon="savedDiagram.shared ? 'lock_open' : 'lock'"
            />

            <Icon v-else icon=" " />
          </div>

          <div class="lassox-diagram__LoadDialog-saved-diagram-text">
            <div
              class="lassox-diagram__LoadDialog-saved-diagram-title"
              v-text="savedDiagram.title || 'Unavngivet diagram'"
            />

            <div
              v-if="savedDiagram.description"
              class="lassox-diagram__LoadDialog-saved-diagram-description"
              v-text="savedDiagram.description"
            />
          </div>

          <div class="lassox-diagram__LoadDialog-saved-diagram-actions">
            <template v-if="defaultDiagram.savedDiagramId === savedDiagram.id">
              <Icon icon="check" />

              <div style="margin-right: 12px" />
            </template>

            <IconButton
              icon="more_vert"
              size="small"
              @click.stop="e => {
                if (!moreDropdown || moreDropdown.savedDiagram !== savedDiagram) {
                  moreDropdown = {
                    opener: e.currentTarget,
                    savedDiagram,
                  }
                  return
                }

                moreDropdown = null
              }"
            />
          </div>
        </BaseButton>

        <DropdownMenu
          v-if="moreDropdown"
          :opener="moreDropdown.opener"
          :close="() => {
            moreDropdown = null
          }"
        >
          <DropdownMenuItem
            label="Rediger"
            icon="edit"
            @click="() => showEditDiagramDialog(moreDropdown.savedDiagram)"
          />

          <DropdownMenuItem
            v-if="diagram.methods.deleteSavedDiagram"
            label="Slet"
            icon="delete"
            :disabled="(moreDropdown.savedDiagram.ownerUserId || '') !== diagram.userId"
            @click="() => showConfirmDeleteDiagramDialog(moreDropdown.savedDiagram)"
          />
        </DropdownMenu>
      </div>
    </template>

    <template v-slot:actions>
      <CheckBoxField
        v-if="canSetDefault"
        label="Åbn som standard"
        :disabled="loading || !selectedDiagram"
        style="margin-right: 16px"
        v-model="setAsDefault"
      />

      <div style="margin: auto" />

      <ButtonGroup align="right">
        <Button
          v-if="diagram.hasActiveDiagram"
          label="Luk"
          :disabled="loading"
          @click="close"
        />

        <Button
          label="Indlæs"
          type="primary"
          :disabled="loading || !selectedDiagram"
          @click="() => {
            if (selectedDiagram === 'new') load()
            else load(selectedDiagram)
          }"
        />
      </ButtonGroup>
    </template>
  </Dialog>
</template>

<script lang="ts">
import { Vue, Component, Inject } from 'vue-property-decorator'
import Dialog from './Dialog.vue'
import LoadingSpinner from './LoadingSpinner.vue'
import BaseButton from './BaseButton.vue'
import Icon from './Icon.vue'
import IconButton from './IconButton.vue'
import DropdownMenu from './DropdownMenu.vue'
import DropdownMenuItem from './DropdownMenuItem.vue'
import CheckBoxField from './CheckBoxField.vue'
import ButtonGroup from './ButtonGroup.vue'
import Button from './Button.vue'
import type DiagramVm from './Diagram.vue'
import type Diagram from '../diagram'
import type SavedDiagram from '../types/SavedDiagram'
import EditDiagramDialog from './EditDiagramDialog.vue'
import cloneDeep from 'lodash.clonedeep'
import ConfirmDeleteDiagramDialog from './ConfirmDeleteDiagramDialog.vue'

@Component({
  components: {
    Dialog,
    LoadingSpinner,
    BaseButton,
    Icon,
    IconButton,
    DropdownMenu,
    DropdownMenuItem,
    CheckBoxField,
    ButtonGroup,
    Button,
  },
})

export default class LoadDialog extends Vue {
  @Inject()
  readonly diagramVm!: DiagramVm

  @Inject()
  readonly diagram!: Diagram

  loading = false

  selectedDiagram: SavedDiagram | 'new' | null = null
  defaultDiagram: Diagram['defaultDiagram'] = {}

  moreDropdown: {
    opener: HTMLElement
    savedDiagram: SavedDiagram
  } | null = null

  get canSetDefault () {
    return !!this.diagram.methods.setDefaultDiagram || this.diagram.saveSettingsToLocalStorage
  }

  get setAsDefault () {
    if (!this.selectedDiagram || !this.defaultDiagram) return false
    if (this.selectedDiagram === 'new') return this.defaultDiagram.new === true
    return this.defaultDiagram.savedDiagramId === this.selectedDiagram.id
  }

  set setAsDefault (value) {
    if (!value || !this.selectedDiagram) {
      this.diagram.defaultDiagram = {}
      return
    }

    if (this.selectedDiagram === 'new') {
      this.diagram.defaultDiagram = { new: true }
      return
    }

    this.diagram.defaultDiagram = { savedDiagramId: this.selectedDiagram.id }
  }

  get defaultDiagramChanged () {
    return (
      this.defaultDiagram.new !== this.diagram.defaultDiagram.new
      || this.defaultDiagram.savedDiagramId !== this.diagram.defaultDiagram.savedDiagramId
    )
  }

  created () {
    this.$watch(
      () => this.diagram.savedDiagrams,
      () => this.selectedDiagram = null,
      { immediate: true },
    )

    this.$watch(
      () => this.diagram.defaultDiagram,
      defaultDiagram => this.defaultDiagram = defaultDiagram,
      { immediate: true },
    )
  }

  close () {
    this.diagram.setDefaultDiagram(this.defaultDiagram)

    this.$emit('close')
  }

  async load (savedDiagram?: SavedDiagram) {
    this.loading = true

    const tasks: Promise<any>[] = []

    tasks.push(this.diagram.load(savedDiagram))
    if (this.defaultDiagramChanged) tasks.push(this.diagram.setDefaultDiagram(this.defaultDiagram))

    await Promise.all(tasks)

    this.close()

    this.loading = false
  }

  showEditDiagramDialog (savedDiagram: SavedDiagram) {
    this.diagram.store.showDialog(EditDiagramDialog, {
      savedDiagram,
      save: async (fields: { title: string, description: string, shared: boolean }) => {
        savedDiagram = cloneDeep(savedDiagram)
        savedDiagram.title = fields.title
        savedDiagram.description = fields.description
        savedDiagram.shared = fields.shared

        await this.diagram.updateSavedDiagram(savedDiagram)

        this.loading = true

        this.diagram.loadSavedDiagrams().then(() => {
          this.loading = false
        })
      },
    })
  }

  showConfirmDeleteDiagramDialog (savedDiagram: SavedDiagram) {
    this.diagram.store.showDialog(ConfirmDeleteDiagramDialog, { savedDiagram })
  }
}
</script>

