<template>
  <div
    class="lassox-diagram__Customizer"
    tabindex="-1"
    @focusout="onFocusOut"
  >
    <!-- <div
      v-if="compact"
      class="lassox-diagram__Customizer_header"
    >
      <div class="lassox-diagram__Customizer_header-title">Tilpas</div>

      <IconButton
        icon="close"
        size="normal"
        @click="() => diagramVm.showCustomizer = false"
      />
    </div> -->

    <div
      v-if="fieldGroups.length"
      class="lassox-diagram__Customizer_fields"
    >
      <!-- <div
        class="lassox-diagram__Customizer_filters-headline"
        style="padding: 16px; padding-bottom: 0"
      >Felter</div> -->

      <CustomizerFieldGroup
        v-for="fieldGroup in fieldGroups"
        :key="fieldGroup.id"
        :fieldGroup="fieldGroup"
      />
    </div>

    <div
      v-if="diagram.fieldGroups.length && diagram.filters.length"
      class="lassox-diagram__Customizer_seperator"
    />

    <div
      v-if="diagram.filters.length"
      class="lassox-diagram__Customizer_filters"
    >
      <div
        class="lassox-diagram__Customizer_filters-headline"
        v-text="'Filtre'"
      />

      <BaseButton
        v-for="filter in diagram.filters"
        :key="filter.id"
        class="lassox-diagram__Customizer_filter-button"
        :label="filter.title"
        :icon="filter.active ? 'check_box' : 'check_box_outline_blank'"
        @click="() => filter.active = !filter.active"
      />
    </div>
  </div>
</template>

<script lang="ts">
import { Vue, Component, Inject } from 'vue-property-decorator'
import IconButton from './IconButton.vue'
import Button from './Button.vue'
import CustomizerFieldGroup from './CustomizerFieldGroup.vue'
import BaseButton from './BaseButton.vue'
import type DiagramVm from './Diagram.vue'
import type { default as Diagram, Field, FieldGroup } from '../diagram'

@Component({
  components: {
    IconButton,
    Button,
    CustomizerFieldGroup,
    BaseButton,
  },
})

export default class Customizer extends Vue {
  @Inject()
  readonly diagramVm!: DiagramVm

  @Inject()
  readonly diagram!: Diagram

  $el!: HTMLElement

  get compact () {
    return this.diagramVm.compact
  }

  get fieldGroups () {
    const fieldGroups: FieldGroup[] = []

    for (const fieldGroup of this.diagram.fieldGroups) {
      const fields: Field[] = []

      for (const field of fieldGroup.fields) {
        if (!field.hideFromCustomizer) fields.push(field)
      }

      if (fields.length) fieldGroups.push({
        ...fieldGroup,
        fields,
      })
    }

    return fieldGroups
  }

  mounted () {
    this.$watch(
      () => this.diagramVm.showCustomizer,
      showCustomizer => {
        if (this.compact && showCustomizer) this.$el.focus()
      },
    )
  }

  onFocusOut (e: FocusEvent) {
    if (!this.compact) return
    if (e.relatedTarget instanceof HTMLElement && this.$el.contains(e.relatedTarget)) return
    this.diagramVm.showCustomizer = false
  }
}
</script>

