<template>
  <div class="lassox-diagram__GraphContextMenu">
    <div
      ref="positionEl"
      class="lassox-diagram__GraphContextMenu-position"
      :style="{
        top: `${position.y}px`,
        left: `${position.x}px`,
      }"
    />

    <ContextMenu
      v-if="show"
      :position="position"
      :actions="actions"
      :close="() => close()"
    />
  </div>
</template>

<script lang="ts">
import { Vue, Component, Inject } from 'vue-property-decorator'
import ContextMenu from './ContextMenu.vue'
import DropdownMenu from './DropdownMenu.vue'
import DropdownMenuItem from './DropdownMenuItem.vue'
import DropdownMenuDivider from './DropdownMenuDivider.vue'
import AddRelationDropdownMenu, { getActions as getAddRelationActions } from './AddRelationDropdownMenu.vue'
import { getActions as getLayoutActions } from './LayoutDropdownMenu.vue'
import Diagram, { ContextItem, ContextMenuAction, ContextMenuActions, createContextItems, Entity } from '../diagram'
import type { Change } from '../types/DiagramData'
import type DiagramVm from './Diagram.vue'
import type Graph from './Graph.vue'
import AddEntityDialog from './AddEntityDialog.vue'

@Component({
  components: {
    ContextMenu,
    DropdownMenu,
    DropdownMenuItem,
    DropdownMenuDivider,
    AddRelationDropdownMenu,
  },
})

export default class GraphContextMenu extends Vue {
  @Inject()
  readonly diagram!: Diagram

  @Inject()
  readonly diagramVm!: DiagramVm

  $refs!: {
    positionEl?: HTMLElement
  }

  showAddDropdownMenu = false

  get graphVm () {
    return this.$parent as Graph
  }

  get show () {
    return this.graphVm.contextMenu.show
  }

  set show (show: boolean) {
    this.graphVm.contextMenu.show = show
  }

  get position () {
    return this.graphVm.contextMenu.position
  }

  get modelPosition () {
    return this.graphVm.contextMenu.modelPosition
  }

  get selectedItems () {
    return this.graphVm.contextMenu.selectedItems
  }

  get hasSelectedItems () {
    return !!this.selectedItems.length
  }

  get onlySelectedItem () {
    return this.selectedItems.length === 1 ? this.selectedItems[0] : null
  }

  get context () {
    const selectedItems = createContextItems(this.selectedItems)
    const selectedEntities: ContextItem[] = []
    const selectedRelations: ContextItem[] = []

    for (const item of selectedItems) {
      if (item.isEntity) selectedEntities.push(item)
      else selectedRelations.push(item)
    }

    return {
      position: this.modelPosition,
      selectedItems,
      selectedEntities,
      selectedRelations,
      hasSelectedItems: !!selectedItems.length,
      onlySelectedItem: selectedItems.length === 1 ? selectedItems[0] : null,
      commitChange: (change: Change) => this.diagram.activeDiagram.data.commitChange(change),
    }
  }

  get actions () {
    const { diagram, diagramVm } = this

    const actions: ContextMenuActions = []

    const group1: ContextMenuAction[] = []
    const group2: ContextMenuAction[] = []

    if (diagram.layouts.length && !this.hasSelectedItems) {
      group2.push({
        label: 'Layout',
        submenu: getLayoutActions(diagramVm),
      })
    }

    if (diagram.enableEditing) {
      if (!this.hasSelectedItems) {
        group1.push({
          icon: 'add',
          label: 'Tilføj',
          onClick: this.showAddDialog,
        })

        if (diagram.enableExpand) {
          group1.push({
            label: 'Udvid alle',
            get disabled () { return diagram.activeDiagram.expanding },
            onClick: () => diagram.activeDiagram.expand(),
          })
        }
      } else if (this.onlySelectedItem?.isEntity) {
        group1.push({
          icon: 'add',
          label: 'Tilføj',
          submenu: getAddRelationActions(diagramVm, this.onlySelectedItem),
        })
      }

      if (this.hasSelectedItems) {
        group1.push({
          icon: 'remove',
          label: 'Fjern',
          disabled: !!this.onlySelectedItem?.isEntity && this.onlySelectedItem.isMainEntity,
          onClick: this.removeSelectedItems,
        })

        if (this.diagram.enableExpand) {
          const selectedEntities: Entity[] = []
          for (const item of this.selectedItems) {
            if (item.isEntity) selectedEntities.push(item)
          }

          if (selectedEntities.length) {
            group1.push({
              label: 'Udvid valgte',
              get disabled () { return diagram.activeDiagram.expanding },
              onClick: () => diagram.activeDiagram.expand(selectedEntities),
            })
          }
        }

        if (this.diagram.enableTaxiEditing) {
          const relations = this.selectedItems.filter(item => item.isRelation)
          const customTaxiRelations = relations.filter(item => item.isRelation && item.customTaxi)

          if (customTaxiRelations.length) {
            group1.push({
              icon: 'replay',
              label: customTaxiRelations.length === 1 ? 'Nulstil knækpil' : 'Nulstil knækpile',
              disabled: !customTaxiRelations.length,
              onClick: () => {
                this.diagram.activeDiagram.data.edit({
                  relations: customTaxiRelations.map(relation => ({
                    id: relation.id,
                    customTaxi: null,
                  })),
                })
              },
            })
          }
        }
      }
    }

    if (group1.length) actions.push(group1)
    if (group2.length) actions.push(group2)

    const customActions = this.diagram.methods.getContextMenuActions?.(this.context)

    if (customActions) {
      if (Array.isArray(customActions)) {
        actions.push(...customActions)
      } else {
        if (customActions.before) actions.unshift(...customActions.before)
        if (customActions.after) actions.push(...customActions.after)
      }
    }

    return actions
  }

  showAddDialog () {
    this.diagram.store.showDialog(AddEntityDialog, { position: this.modelPosition })
  }

  removeSelectedItems () {
    const entityIds = new Set<string>()
    const relationIds = new Set<string>()

    for (const item of this.selectedItems) {
      if (item.isEntity) {
        if (item.isMainEntity) continue
        entityIds.add(item.id)
      } else {
        relationIds.add(item.id)
      }
    }

    this.diagram.activeDiagram.data.remove({
      entities: [ ...entityIds ],
      relations: [ ...relationIds ],
    })
  }

  close () {
    this.show = false
    const parentEl = this.$parent?.$el as HTMLElement
    parentEl.focus()
  }
}
</script>

<style lang="scss">
.lassox-diagram__GraphContextMenu {
  &-position {
    position: absolute;
    z-index: 9999;
  }
}
</style>
