<template>
  <Dialog
    class="lassox-diagram__PrintDialog"
    :dismissable="true"
    :title="title"
    size="3x"
    :onClose="close"
  >
    <template v-slot:content>
      <p
        v-if="description"
        v-text="description"
      />

      <EditorFields
        v-if="hasFields"
        style="margin-top: 16px"
      >
        <EditorField
          v-if="diagram.printSettings.orientation === undefined"
          id="print-orientation"
          type="radio-buttons"
          title="Orientering"
          :options="[
            { label: 'Stående', value: 'portrait' },
            { label: 'Liggende', value: 'landscape' },
          ]"
          :editable="!printing"
          v-model="orientation"
        />

        <EditorField
          v-if="diagram.printSettings.size === undefined"
          id="print-size"
          type="radio-buttons"
          title="Størrelse"
          :options="[
            { label: 'A5', value: 'A5' },
            { label: 'A4', value: 'A4' },
            { label: 'A3', value: 'A3' },
          ]"
          :editable="!printing"
          v-model="size"
        />

        <EditorField
          v-if="diagram.printSettings.fitToPaper === undefined && mode !== 'png'"
          id="print-fit"
          type="boolean"
          title="Begræns til én side"
          :editable="!printing"
          v-model="fitToPaper"
        />

        <EditorField
          v-if="diagram.printSettings.includeMargin === undefined && mode !== 'png'"
          id="print-margin"
          type="boolean"
          title="Margen"
          helperText="Inkluder en margen (1 cm) eller udskriv til papirets kant."
          :editable="!printing"
          v-model="includeMargin"
        />
      </EditorFields>
    </template>

    <template v-slot:actions>
      <ButtonGroup align="right">
        <Button
          label="Luk"
          @click="close"
        />

        <Button
          type="primary"
          :label="buttonLabel"
          :disabled="printing"
          @click="confirm"
        />
      </ButtonGroup>
    </template>
  </Dialog>
</template>

<script lang="ts">
import { Vue, Component, Inject, Prop } from 'vue-property-decorator'
import Dialog from './Dialog.vue'
import EditorFields from './EditorFields.vue'
import EditorField from './EditorField.vue'
import ButtonGroup from './ButtonGroup.vue'
import Button from './Button.vue'
import type DiagramVm from './Diagram.vue'
import { isRecord } from '../util/type-guards'

@Component({
  components: {
    Dialog,
    EditorFields,
    EditorField,
    ButtonGroup,
    Button,
  },
})

export default class PrintDialog extends Vue {
  @Inject()
  readonly diagramVm!: DiagramVm

  @Prop({ type: String, required: true })
  readonly mode!: 'print' | 'pdf' | 'png'

  orientation: 'portrait' | 'landscape' = 'landscape'
  size: 'A5' | 'A4' | 'A3' = 'A4'
  fitToPaper = true
  includeMargin = true

  printing = false

  get diagram () {
    return this.diagramVm.diagram
  }

  get hasFields () {
    return (
      this.diagram.printSettings.orientation === undefined
      || this.diagram.printSettings.size === undefined
      || (this.diagram.printSettings.fitToPaper === undefined && this.mode !== 'png')
      || (this.diagram.printSettings.includeMargin === undefined && this.mode !== 'png')
    )
  }

  get title () {
    switch (this.mode) {
      case 'print': return 'Udskriv'
      case 'pdf': return 'Gem som PDF'
      case 'png': return 'Gem som billede'
      default: return 'Udskriv'
    }
  }

  get description () {
    switch (this.mode) {
      case 'print': return this.hasFields
        ? 'Din computers udskriftsindstillinger skal være de samme som de nedenfor valgte.'
        : 'Udskriv diagrammet via din browser.'
      case 'pdf': return 'Gem diagrammet til din computer som PDF.'
      case 'png': return 'Gem diagrammet til din computer i .png format.'
      default: return ''
    }
  }

  get buttonLabel () {
    switch (this.mode) {
      case 'print': return !this.printing ? 'Udskriv' : 'Udskriver...'
      default: return !this.printing ? 'Gem' : 'Gemmer...'
    }
  }

  created () {
    this.loadFromLocalStorage()

    this.$watch(
      () => [this.orientation, this.size, this.fitToPaper, this.includeMargin],
      this.saveToLocalStorage,
      { immediate: true },
    )

    if (!this.hasFields) {
      this.confirm()
    }
  }

  beforeDestroy () {
    this.diagram.eventBus.off('printDone', this.onPrintDone)
  }

  loadFromLocalStorage () {
    if (!this.diagram.saveSettingsToLocalStorage) return

    try {
      const json = localStorage.getItem('lassox-diagram/print-settings')
      if (!json) return

      const settings = JSON.parse(json)
      if (!isRecord(settings)) return

      const { orientation, size, fitToPaper, includeMargin } = settings

      if (this.diagram.printSettings.orientation === undefined && orientation === 'portrait' || orientation === 'landscape') {
        this.orientation = orientation
      }

      if (this.diagram.printSettings.size === undefined && size === 'A5' || size === 'A4' || size === 'A3') {
        this.size = size
      }

      if (this.diagram.printSettings.fitToPaper === undefined && typeof fitToPaper === 'boolean') {
        this.fitToPaper = fitToPaper
      }

      if (this.diagram.printSettings.includeMargin === undefined && typeof includeMargin === 'boolean') {
        this.includeMargin = includeMargin
      }
    } catch {
      return
    }
  }

  saveToLocalStorage () {
    if (!this.diagram.saveSettingsToLocalStorage) return

    try {
      localStorage.setItem('lassox-diagram/print-settings', JSON.stringify({
        orientation: this.orientation,
        size: this.size,
        fitToPaper: this.fitToPaper,
        includeMargin: this.includeMargin,
      }))
    } catch {
      return
    }
  }

  close () {
    this.$emit('close')
  }

  confirm () {
    this.printing = true

    requestAnimationFrame(() => {
      this.diagram.eventBus.one('printDone', this.onPrintDone)

      const paperOrientation = this.diagram.printSettings.orientation ?? this.orientation
      const paperSize = this.diagram.printSettings.size ?? this.size
      let grow = !(this.diagram.printSettings.fitToPaper ?? this.fitToPaper)
      let includeMargin = this.diagram.printSettings.includeMargin ?? this.includeMargin

      if (this.mode === 'png') {
        grow = false
        includeMargin = false
      }

      this.diagram.eventBus.emit({
        name: 'print',
        mode: this.mode,
        paper: true,
        paperOrientation,
        paperSize,
        grow,
        includeMargin,
        scaling: 4,
      })
    })
  }

  onPrintDone ({ file }: { file?: { filename: string, blob: Blob } }) {
    if (file) {
      const url = window.URL.createObjectURL(file.blob)

      const aEl = document.createElement('a')
      aEl.href = url
      aEl.download = file.filename
      document.body.appendChild(aEl)
      aEl.click()
      aEl.remove()

      window.URL.revokeObjectURL(url)
    }

    this.printing = false
    this.close()
  }
}
</script>
