<template>
  <Dialog
    class="lassox-diagram__ConfirmDeleteDiagramDialog"
    :dismissable="true"
    :loading="loading"
    size="3x"
    title="Slet diagram?"
    :content="`Er du sikker på at du vil slette det gemte diagram &quot;${(savedDiagram || diagram.activeDiagram).title || 'Unavngivet diagram'}&quot;?`"
    :onClose="dismiss"
  >
    <template v-slot:actions>
      <ButtonGroup align="right">
        <Button
          label="Fortryd"
          :disabled="loading"
          @click="dismiss"
        />

        <Button
          label="Slet"
          type="primary"
          :disabled="loading"
          @click="confirm"
        />
      </ButtonGroup>
    </template>
  </Dialog>
</template>

<script lang="ts">
import { Vue, Component, Prop, Inject } from 'vue-property-decorator'
import Dialog from './Dialog.vue'
import LoadingSpinner from './LoadingSpinner.vue'
import ButtonGroup from './ButtonGroup.vue'
import Button from './Button.vue'
import type Diagram from '../diagram'
import SavedDiagram, { createSavedDiagram } from '../types/SavedDiagram'

@Component({
  components: {
    Dialog,
    LoadingSpinner,
    ButtonGroup,
    Button,
  },
})

export default class ConfirmDeleteDiagramDialog extends Vue {
  @Inject()
  readonly diagram!: Diagram

  @Prop(Object)
  readonly savedDiagram?: SavedDiagram

  @Prop(Function)
  readonly onConfirm?: () => void

  @Prop(Function)
  readonly onDismiss?: () => void

  loading = false

  close () {
    this.$emit('close')
  }

  async confirm () {
    let { savedDiagram } = this

    const isActiveDiagram = !savedDiagram

    if (savedDiagram) {
      if (!savedDiagram.id) return
    } else {
      if (!this.diagram.activeDiagram.id) return
      savedDiagram = createSavedDiagram(this.diagram)
    }

    this.loading = true

    await this.diagram.deleteSavedDiagram(savedDiagram)

    if (isActiveDiagram) await this.diagram.load()

    this.loading = false

    this.close()
    this.onConfirm?.()
  }

  dismiss () {
    this.close()
    this.onDismiss?.()
  }
}
</script>
