<template>
  <div class="lassox-diagram__ContextMenu">
    <div
      ref="positionEl"
      class="lassox-diagram__GraphContextMenu-position"
      :style="{
        top: `${position.y}px`,
        left: `${position.x}px`,
      }"
    />

    <DropdownMenu
      v-for="menu in menus"
      :key="menu.id"
      :opener="menu.opener"
      :close="menu.close"
      :closeOnLongMouseOut="menu.closeOnLongMouseOut"
    >
      <template v-for="(items, groupI) in menu.actions">
        <DropdownMenuDivider
          v-if="groupI"
          :key="`group-${groupI}-divider`"
        />

        <DropdownMenuItem
          v-for="item in items"
          :key="item.id"
          :ref="item.id"
          :icon="item.icon"
          :iconColor="item.iconColor"
          :label="item.label"
          :trailingIcon="item.trailingIcon"
          :disabled="item.disabled"
          :closeMenuOnClick="!item.submenu"
          @longmouseover="() => {
            if (item.submenu) item.submenu.opener = $refs[item.id][0]
          }"
          @click="() => {
            if (item.submenu) item.submenu.opener = item.submenu.opener ? null : $refs[item.id][0]
            else if (item.onClick) item.onClick()
          }"
        />
      </template>
    </DropdownMenu>
  </div>
</template>

<script lang="ts">
import type { ContextMenuAction, ContextMenuActions } from '../diagram'
import { Vue, Component, Prop } from 'vue-property-decorator'
import DropdownMenu from './DropdownMenu.vue'
import DropdownMenuDivider from './DropdownMenuDivider.vue'
import DropdownMenuItem from './DropdownMenuItem.vue'

const normalizeActions = (actions: ContextMenuActions) => {
  const groups: ContextMenuAction[][] = []

  let grouping = false
  let newGroup: ContextMenuAction[] = []

  const startGrouping = () => {
    grouping = true
    newGroup = []
    groups.push(newGroup)
  }

  const stopGrouping = () => {
    grouping = false
    newGroup = []
  }

  for (const item of actions) {
    if (Array.isArray(item)) {
      if (grouping) stopGrouping()
      startGrouping()
      for (const action of item) {
        if (action) newGroup.push(action)
      }
      stopGrouping()
    } else {
      if (!grouping) startGrouping()
      const action = item
      if (action) newGroup.push(action)
    }
  }

  return groups.filter(group => group.length)
}

interface StateMenu {
  id: string
  opener: HTMLElement | null
  close: () => void
  closeOnLongMouseOut?: boolean
  actions: StateMenuAction[][]
}

interface StateMenuAction {
  id: string
  icon?: string
  iconColor?: string
  label: string
  trailingIcon?: string
  disabled?: boolean
  submenu?: StateMenu
  onClick?: () => void
}

@Component({
  components: {
    DropdownMenu,
    DropdownMenuDivider,
    DropdownMenuItem,
  },
})

export default class ContextMenu extends Vue {
  @Prop({ type: Object, required: true })
  readonly position!: { x: number, y: number }

  @Prop({ type: Function, required: true })
  readonly close!: () => void

  @Prop({ type: Array, required: true })
  readonly actions!: ContextMenuActions

  $refs!: {
    positionEl?: HTMLElement
  }

  menus: StateMenu[] = []

  mounted () {
    this.$watch(
      () => this.actions,
      () => {
        const menusMap = new Map<ContextMenuActions, StateMenu>()

        let menuI = 0

        const getMenu = (actions: ContextMenuActions): StateMenu => {
          let menu = menusMap.get(actions)

          if (!menu) {
            const isMain = !menuI

            const menuId = `menu-${menuI}`

            menuI++

            menu = {
              id: menuId,
              opener: isMain && this.$refs.positionEl || null,
              close: () => {
                if (isMain) this.close()
                else if (menu) menu.opener = null
              },
              closeOnLongMouseOut: !isMain,
              actions: [],
            }

            menusMap.set(actions, menu)

            let hasIcon = false
            let hasTrailingIcon = false

            menu.actions = normalizeActions(actions).map((group, groupI) => {
              const groupId = `${menuId}-group-${groupI}`

              const actions = group.map((action, actionI): StateMenuAction => {
                if (action.icon) hasIcon = true
                if (action.submenu) hasTrailingIcon = true

                return {
                  id: `${groupId}-action-${actionI}`,
                  icon: action.icon,
                  iconColor: action.iconColor,
                  label: action.label,
                  trailingIcon: action.submenu ? 'arrow_right' : '',
                  disabled: action.disabled || (action.submenu && !action.submenu.length),
                  submenu: action.submenu && getMenu(action.submenu),
                  onClick: () => action.onClick?.(),
                }
              })

              return actions
            })

            if (hasIcon || hasTrailingIcon) {
              for (const group of menu.actions) {
                for (const action of group) {
                  if (hasIcon && !action.icon) action.icon = ' '
                  if (hasTrailingIcon && !action.trailingIcon) action.trailingIcon = ' '
                }
              }
            }
          }

          return menu
        }

        const menu = getMenu(this.actions)

        if (!menu.actions.length) {
          this.close()
          return
        }

        this.menus = [ ...menusMap.values() ]
      },
      { immediate: true, deep: true },
    )
  }
}
</script>
