<template>
  <div
    class="lassox-diagram__CustomScroll"
    :style="{
      marginTop: `${-paddingTop}px`,
      marginLeft: `${-paddingLeft}px`,
      marginRight: `${-paddingRight}px`,
      marginBottom: `${-paddingBottom}px`,
    }"
  >
    <div
      ref="scrollbarSizerEl"
      class="lassox-diagram__CustomScroll-scrollbar-sizer"
    >
      <div
        ref="scrollbarSizerInnerEl"
        class="lassox-diagram__CustomScroll-scrollbar-sizer-inner"
      />
    </div>

    <div
      ref="wrapperEl"
      class="lassox-diagram__CustomScroll-wrapper"
      :style="{
        marginRight: `${-100 - scrollbarWidth}px`,
        marginBottom: `${-100 - scrollbarHeight}px`,
      }"
      @scroll.passive="onScroll"
    >
      <div
        class="lassox-diagram__CustomScroll-content"
        :style="{
          paddingTop: `${paddingTop}px`,
          paddingLeft: `${paddingLeft}px`,
          paddingRight: `${paddingRight}px`,
          paddingBottom: `${paddingBottom}px`,
        }"
      >
        <slot />
      </div>
    </div>

    <CustomScrollBar
      axis="y"
      :viewSize="wrapperHeight"
      :contentSize="wrapperScrollHeight"
      :scroll="wrapperScrollTop"
      :paddingTop="paddingTop"
      :paddingLeft="paddingLeft"
      :paddingRight="paddingRight"
      :paddingBottom="paddingBottom"
      @updateScroll="scrollTop => wrapperEl.scrollTop = scrollTop"
    />
  </div>
</template>

<script lang="ts">
import { Vue, Component, Ref, Prop } from 'vue-property-decorator'
import CustomScrollBar from './CustomScrollBar.vue'

@Component({
  components: {
    CustomScrollBar,
  },
})

export default class CustomScroll extends Vue {
  @Ref()
  readonly scrollbarSizerEl?: HTMLElement

  @Ref()
  readonly scrollbarSizerInnerEl?: HTMLElement

  @Ref()
  readonly wrapperEl?: HTMLElement

  @Prop({ type: Number, default: () => 0 })
  readonly paddingTop!: number

  @Prop({ type: Number, default: () => 0 })
  readonly paddingLeft!: number

  @Prop({ type: Number, default: () => 0 })
  readonly paddingRight!: number

  @Prop({ type: Number, default: () => 0 })
  readonly paddingBottom!: number

  scrollbarWidth = 0
  scrollbarHeight = 0

  rafId: number | null = null

  wrapperHeight = 0
  wrapperScrollHeight = 0
  wrapperScrollTop = 0

  _scrollThrottled = false

  get canScrollY () {
    return this.wrapperScrollHeight > this.wrapperHeight
  }

  get canScrollUp () {
    return this.canScrollY && !!this.wrapperScrollTop
  }

  get canScrollDown () {
    return this.canScrollY && (this.wrapperScrollHeight - this.wrapperHeight - this.wrapperScrollTop >= 1)
  }

  updateScrollValues () {
    this.wrapperScrollTop = this.wrapperEl?.scrollTop ?? 0
  }

  onScroll () {
    if (this._scrollThrottled) return

    this._scrollThrottled = true
    this.updateScrollValues()

    requestAnimationFrame(() => {
      this.updateScrollValues()
      this._scrollThrottled = false
    })
  }

  mounted () {
    const {
      scrollbarSizerEl,
      scrollbarSizerInnerEl,
      wrapperEl,
    } = this

    if (!scrollbarSizerEl || !scrollbarSizerInnerEl || !wrapperEl) throw 'Something went wrong...'

    this.scrollbarWidth = scrollbarSizerEl.clientWidth - scrollbarSizerInnerEl.clientWidth
    this.scrollbarHeight = scrollbarSizerEl.clientHeight - scrollbarSizerInnerEl.clientHeight

    this.wrapperScrollTop = wrapperEl.scrollTop

    const handler = () => {
      this.wrapperHeight = wrapperEl.clientHeight - 100
      this.wrapperScrollHeight = wrapperEl.scrollHeight - 100

      this.rafId = requestAnimationFrame(handler)
    }

    handler()
  }

  beforeDestroy () {
    if (this.rafId !== null) {
      cancelAnimationFrame(this.rafId)
      this.rafId = null
    }
  }
}
</script>

<style lang="scss">
.lassox-diagram__CustomScroll {
  position: relative;
  display: flex;
  flex-direction: column;
  overflow: hidden;

  &-scrollbar-sizer,
  &-wrapper {
    overflow: hidden;
    overflow-y: scroll;

    &::-webkit-scrollbar {
      display: none;
    }

    scrollbar-width: 0;
    scrollbar-width: none;
    -ms-overflow-style: none;
  }

  &-scrollbar-sizer {
    position: absolute;
    visibility: hidden;
    width: 100px;
    height: 100px;

    &-inner {
      width: 100%;
      height: 100%;
    }
  }

  &-wrapper {
    position: relative;
    padding-right: 100px;
    padding-bottom: 100px;
    margin-right: -100px;
    margin-bottom: -100px;
  }
}
</style>
